INSERT INTO `books` VALUES (1,'Cho tôi xin một vé đi tuổi thơ',1,1,50000.00,10,'Cuốn sách kể về tuổi thơ hồn nhiên qua góc nhìn của nhân vật Mùi. Những câu chuyện giản dị nhưng sâu sắc giúp người đọc nhớ lại thời thơ ấu đầy mơ mộng, đồng thời gửi gắm nhiều suy ngẫm về cách người lớn nhìn nhận thế giới của trẻ con. Đây là một trong những tác phẩm nổi bật và được yêu thích nhất của Nguyễn Nhật Ánh.','http://res.cloudinary.com/dqiefayjh/image/upload/v1774688881/books/qmxq98fwcklxzm5akk1u.jpg',2008,'978-604-1-08532-1','NXB Trẻ','Tiếng Việt','Bìa mềm',0,'cho-toi-xin-mot-ve-di-tuoi-tho',70000.00,0),(2,'Rich Dad Poor Dad',2,3,120000.00,5,'Rich Dad Poor Dad (Cha Giàu Cha Nghèo) của Robert T. Kiyosaki là một trong những cuốn sách tài chính cá nhân nổi tiếng nhất thế giới. Thông qua những bài học từ hai người cha với hai quan điểm khác nhau về tiền bạc, tác giả chia sẻ cách tư duy về tài sản, đầu tư và tự do tài chính.\n\nCuốn sách khuyến khích người đọc xây dựng kiến thức tài chính, tạo ra nguồn thu nhập thụ động và thay đổi cách nhìn nhận về công việc, tiền bạc cũng như sự giàu có trong cuộc sống.','http://res.cloudinary.com/dqiefayjh/image/upload/v1774690124/books/gppx81otw3z0d2h0t3n4.webp',1997,'978-604-77-3329-0','NXB Tổng Hợp TP.HCM','Tiếng Việt','Bìa mềm',0,'rich-dad-poor-dad',160000.00,0),(3,'Mắt Biếc',1,1,85000.00,20,'Mắt Biếc là một trong những tác phẩm nổi bật của Nguyễn Nhật Ánh, kể về câu chuyện tình yêu đơn phương đầy day dứt của Ngạn dành cho Hà Lan – cô gái có đôi mắt xanh biếc khiến bao người say đắm. Bối cảnh làng quê yên bình cùng những ký ức tuổi thơ trong sáng tạo nên một câu chuyện nhẹ nhàng nhưng sâu lắng.\r\n\r\nKhông chỉ là câu chuyện tình yêu, cuốn sách còn gợi lên nhiều cảm xúc về tuổi trẻ, sự trưởng thành và những tiếc nuối trong cuộc sống. Với lối viết giản dị nhưng giàu cảm xúc, Mắt Biếc đã chạm đến trái tim của nhiều thế hệ độc giả và trở thành một trong những tác phẩm được yêu thích nhất.','http://res.cloudinary.com/dqiefayjh/image/upload/v1774688866/books/pyfswrt848psaboo6ilf.jpg',1990,'978-604-1-08531-4','NXB Trẻ','Tiếng Việt','Bìa mềm',0,'mat-biec',110000.00,0),(4,'Tôi Thấy Hoa Vàng Trên Cỏ Xanh',1,1,90000.00,15,'Tôi Thấy Hoa Vàng Trên Cỏ Xanh là một tác phẩm nổi tiếng của Nguyễn Nhật Ánh, kể về tuổi thơ của hai anh em Thiều và Tường tại một làng quê yên bình. Những câu chuyện xoay quanh cuộc sống thường ngày, tình bạn, tình anh em và những rung động đầu đời được khắc họa một cách chân thật, giản dị nhưng đầy cảm xúc.\r\n\r\nCuốn sách không chỉ gợi lại ký ức tuổi thơ trong sáng mà còn gửi gắm nhiều thông điệp sâu sắc về tình người, sự trưởng thành và những bài học trong cuộc sống. Với giọng văn nhẹ nhàng, gần gũi, tác phẩm đã chạm đến trái tim của đông đảo độc giả và trở thành một trong những cuốn sách được yêu thích nhất của Nguyễn Nhật Ánh.','http://res.cloudinary.com/dqiefayjh/image/upload/v1774690308/books/v8zgjdvqjfoq2dim2avo.jpg',2010,'978-604-1-08533-8','NXB Trẻ','Tiếng Việt','Bìa mềm',0,'toi-thay-hoa-vang-tren-co-xanh',90000.00,0),(5,'Kính Vạn Hoa',1,1,75000.00,18,'Kính Vạn Hoa là bộ truyện dài nổi tiếng của Nguyễn Nhật Ánh, xoay quanh cuộc sống học đường và những câu chuyện thú vị của nhóm bạn Quý ròm, Tiểu Long và Hạnh. Mỗi tập truyện là một câu chuyện riêng biệt, đầy hài hước và gần gũi với lứa tuổi học sinh.\r\n\r\nBộ truyện không chỉ mang tính giải trí mà còn truyền tải nhiều bài học ý nghĩa về tình bạn, gia đình và cuộc sống. Với lối viết dí dỏm, sinh động, Kính Vạn Hoa đã trở thành một phần ký ức tuổi thơ của nhiều thế hệ độc giả Việt Nam.','http://res.cloudinary.com/dqiefayjh/image/upload/v1774690173/books/p2mb5frhbu2pxsjwfdaf.jpg',1995,'978-604-1-08534-5','NXB Trẻ','Tiếng Việt','Bìa mềm',0,'kinh-van-hoa',75000.00,0),(6,'Đắc Nhân Tâm',3,4,95000.00,30,'Đắc Nhân Tâm là một trong những cuốn sách nổi tiếng nhất của Dale Carnegie, tập trung vào nghệ thuật giao tiếp và cách ứng xử trong cuộc sống. Thông qua những nguyên tắc đơn giản nhưng hiệu quả, cuốn sách giúp người đọc hiểu cách tạo thiện cảm, xây dựng mối quan hệ và gây ảnh hưởng tích cực đến người khác.\r\n\r\nKhông chỉ dừng lại ở lý thuyết, cuốn sách còn đưa ra nhiều ví dụ thực tế, giúp người đọc dễ dàng áp dụng vào công việc và cuộc sống hàng ngày. Với giá trị vượt thời gian, Đắc Nhân Tâm đã trở thành một trong những cuốn sách kỹ năng sống bán chạy nhất thế giới và là lựa chọn hàng đầu cho những ai muốn phát triển bản thân.','http://res.cloudinary.com/dqiefayjh/image/upload/v1774690190/books/yhwinkgexnff31gfsltj.webp',1936,'978-604-77-1540-1','NXB Tổng Hợp TP.HCM','Tiếng Việt','Bìa mềm',0,'dac-nhan-tam',120000.00,0),(7,'Nghĩ Giàu Làm Giàu',4,3,110000.00,12,'Nghĩ Giàu Làm Giàu là một trong những cuốn sách kinh điển về phát triển bản thân và tư duy thành công. Tác giả đã nghiên cứu những người giàu có và thành công để rút ra các nguyên tắc giúp đạt được mục tiêu trong cuộc sống.\r\n\r\nCuốn sách nhấn mạnh sức mạnh của suy nghĩ, niềm tin và sự kiên trì trong việc đạt được thành công. Đây là tài liệu quan trọng cho những ai muốn thay đổi tư duy và phát triển bản thân cả về tài chính lẫn cuộc sống.','http://res.cloudinary.com/dqiefayjh/image/upload/v1774690214/books/nyr8hk2zletovgvptkbs.jpg',1937,'978-604-77-2345-1','NXB Tổng Hợp TP.HCM','Tiếng Việt','Bìa mềm',0,'nghi-giau-lam-giau',110000.00,0),(8,'Sapiens: Lược Sử Loài Người',5,5,150000.00,2,'Sapiens: Lược Sử Loài Người của Yuval Noah Harari là cuốn sách khám phá toàn bộ hành trình phát triển của loài người từ thời kỳ săn bắt hái lượm đến xã hội hiện đại. Tác giả phân tích những cuộc cách mạng quan trọng như cách mạng nhận thức, cách mạng nông nghiệp và cách mạng khoa học đã định hình nền văn minh nhân loại.\n\nBằng lối viết hấp dẫn và góc nhìn liên ngành, cuốn sách giúp người đọc hiểu rõ hơn về lịch sử, văn hóa, kinh tế và những yếu tố đã tạo nên thế giới ngày nay.','http://res.cloudinary.com/dqiefayjh/image/upload/v1774690231/books/sdkj3ktiuwsqcfnq8g4v.jpg',2011,'978-604-77-3400-6','NXB Tri Thức','Tiếng Việt','Bìa mềm',0,'sapiens-luoc-su-loai-nguoi',140000.00,0),(9,'Nhà Giả Kim',6,7,88000.00,25,'Nhà Giả Kim kể về hành trình của Santiago – một chàng chăn cừu trẻ tuổi đi tìm kho báu theo giấc mơ của mình. Trên con đường đó, cậu gặp nhiều người và trải qua nhiều thử thách, từ đó học được những bài học quý giá về cuộc sống.\r\n\r\nCuốn sách mang thông điệp sâu sắc về việc theo đuổi ước mơ, lắng nghe trái tim và tin vào hành trình của bản thân. Với lối viết đơn giản nhưng đầy triết lý, tác phẩm đã truyền cảm hứng cho hàng triệu độc giả trên thế giới.','http://res.cloudinary.com/dqiefayjh/image/upload/v1774690258/books/klnlgnrmefvemrco392g.jpg',1988,'978-604-2-00351-2','NXB Hội Nhà Văn','Tiếng Việt','Bìa mềm',0,'nha-gia-kim',110000.00,0),(10,'1984',7,7,92000.00,14,'1984 là một tiểu thuyết kinh điển của George Orwell, mô tả một xã hội toàn trị nơi mọi hành động và suy nghĩ của con người đều bị kiểm soát. Nhân vật chính Winston Smith sống trong một thế giới bị giám sát chặt chẽ, nơi sự thật bị bóp méo và tự do cá nhân gần như không tồn tại.\r\n\r\nCuốn sách không chỉ là một câu chuyện giả tưởng mà còn là lời cảnh báo sâu sắc về quyền lực, sự kiểm soát và mất tự do. Với giá trị vượt thời gian, 1984 vẫn luôn là một trong những tác phẩm được đánh giá cao trong văn học thế giới.','http://res.cloudinary.com/dqiefayjh/image/upload/v1774690322/books/wtkpvjstd3q5ughdjuqe.jpg',1949,'978-604-2-01984-0','NXB Hội Nhà Văn','Tiếng Việt','Bìa mềm',0,'1984',92000.00,0),(11,'Trại Súc Vật',7,7,79000.00,16,'Trại Súc Vật là một tác phẩm nổi tiếng của George Orwell, sử dụng hình ảnh các loài vật để ẩn dụ cho xã hội loài người. Câu chuyện xoay quanh cuộc nổi dậy của các con vật chống lại con người để xây dựng một xã hội bình đẳng, nhưng dần dần lại bị biến chất bởi quyền lực.\r\n\r\nThông qua lối kể chuyện đơn giản nhưng sâu sắc, cuốn sách phản ánh những vấn đề về chính trị, quyền lực và sự tha hóa. Đây là một tác phẩm mang tính cảnh tỉnh, giúp người đọc hiểu rõ hơn về bản chất của xã hội và con người.','http://res.cloudinary.com/dqiefayjh/image/upload/v1774690337/books/gdgpjcbeglt7kza7u7fd.jpg',1945,'978-604-2-01945-1','NXB Hội Nhà Văn','Tiếng Việt','Bìa mềm',0,'trai-suc-vat',79000.00,0),(12,'Harry Potter và Hòn Đá Phù Thủy',8,7,120000.00,20,'Harry Potter và Hòn Đá Phù Thủy là phần đầu tiên trong loạt truyện nổi tiếng về cậu bé phù thủy Harry Potter. Câu chuyện bắt đầu khi Harry phát hiện mình là một phù thủy và được mời nhập học tại trường Hogwarts – nơi đào tạo phép thuật. Tại đây, cậu kết bạn với Ron và Hermione, đồng thời khám phá thế giới kỳ diệu đầy bí ẩn.\r\n\r\nKhông chỉ là một câu chuyện phiêu lưu hấp dẫn, cuốn sách còn truyền tải những thông điệp sâu sắc về tình bạn, lòng dũng cảm và sự lựa chọn giữa cái thiện và cái ác. Với cốt truyện lôi cuốn và thế giới phép thuật độc đáo, tác phẩm đã trở thành một trong những cuốn sách được yêu thích nhất trên toàn thế giới.','http://res.cloudinary.com/dqiefayjh/image/upload/v1774690377/books/zterccekdlgkqw3jy6em.jpg',1997,'978-604-1-12345-7','NXB Trẻ','Tiếng Việt','Bìa mềm',0,'harry-potter-va-hon-da-phu-thuy',120000.00,0),(13,'Dế Mèn Phiêu Lưu Ký',9,8,65000.00,22,'Dế Mèn Phiêu Lưu Ký là tác phẩm nổi tiếng của Tô Hoài, kể về hành trình trưởng thành của chú Dế Mèn – một chàng dế trẻ tuổi, bồng bột nhưng dũng cảm. Từ những sai lầm ban đầu, Dế Mèn bắt đầu chuyến phiêu lưu qua nhiều vùng đất, gặp gỡ nhiều người bạn và trải qua vô số thử thách.\r\n\r\nThông qua câu chuyện giàu tính nhân văn, cuốn sách truyền tải những bài học sâu sắc về tình bạn, lòng dũng cảm và trách nhiệm với hành động của bản thân. Với lối kể chuyện sinh động, gần gũi, tác phẩm không chỉ dành cho thiếu nhi mà còn chạm đến trái tim của nhiều thế hệ độc giả.','http://res.cloudinary.com/dqiefayjh/image/upload/v1774690396/books/oukx48srxtgj38f1c8mk.jpg',1941,'978-604-09-2345-6','NXB Kim Đồng','Tiếng Việt','Bìa mềm',0,'de-men-phieu-luu-ky',65000.00,0),(14,'Chí Phèo',10,8,55000.00,18,'Chí Phèo là tác phẩm tiêu biểu của Nam Cao, phản ánh số phận bi kịch của người nông dân trong xã hội cũ. Nhân vật Chí Phèo từ một người lương thiện bị đẩy vào con đường tha hóa, trở thành kẻ bị xã hội ruồng bỏ.\r\n\r\nTác phẩm không chỉ tố cáo xã hội bất công mà còn thể hiện khát vọng được làm người lương thiện của những con người bị áp bức. Với giá trị hiện thực và nhân đạo sâu sắc, đây là một trong những tác phẩm kinh điển của văn học Việt Nam.','http://res.cloudinary.com/dqiefayjh/image/upload/v1774690424/books/plb17scugkwtsztgmmuo.jpg',1941,'978-604-1-09876-5','NXB Văn Học','Tiếng Việt','Bìa mềm',0,'chi-pheo',55000.00,0),(15,'Cha Giàu Cha Nghèo',2,3,120000.00,15,'Cuốn sách kể về những bài học tài chính từ hai người cha với tư duy hoàn toàn khác nhau về tiền bạc. Qua đó, người đọc hiểu được sự khác biệt giữa việc làm việc vì tiền và để tiền làm việc cho mình.\r\n\r\nVới cách viết dễ hiểu, sách giúp người đọc nắm được các khái niệm cơ bản như tài sản, tiêu sản và đầu tư, đồng thời truyền cảm hứng để đạt được tự do tài chính.','http://res.cloudinary.com/dqiefayjh/image/upload/v1774690463/books/nequcyqz16rrzk2z3irw.jpg',1997,'978-604-77-3330-6','NXB Tổng Hợp TP.HCM','Tiếng Việt','Bìa mềm',0,'cha-giau-cha-ngheo',120000.00,0),(16,'Homo Deus',5,5,160000.00,7,'Homo Deus là phần tiếp theo của Sapiens, tập trung vào tương lai của loài người trong bối cảnh công nghệ phát triển mạnh mẽ. Cuốn sách đặt ra những câu hỏi lớn về việc con người sẽ đi về đâu khi trí tuệ nhân tạo và công nghệ sinh học ngày càng chi phối cuộc sống.\r\n\r\nVới góc nhìn sâu sắc, tác giả phân tích những khả năng như con người trở nên “bất tử”, nâng cấp trí tuệ hay mất đi vai trò trước máy móc. Đây là cuốn sách giúp người đọc suy ngẫm về tương lai và vị trí của con người trong thế giới hiện đại.','http://res.cloudinary.com/dqiefayjh/image/upload/v1774690480/books/lxyrngukbvyhwnsx8tea.jpg',2015,'978-604-77-4521-7','NXB Tri Thức','Tiếng Việt','Bìa mềm',0,'homo-deus',200000.00,0),(17,'Quẳng Gánh Lo Đi Mà Vui Sống',3,4,85000.00,20,'Cuốn sách giúp người đọc nhận ra nguyên nhân của lo âu và cách kiểm soát suy nghĩ tiêu cực trong cuộc sống. Thông qua những nguyên tắc đơn giản và ví dụ thực tế, tác giả hướng dẫn cách sống tích cực và giảm căng thẳng.\r\n\r\nKhông chỉ mang tính lý thuyết, sách còn cung cấp nhiều phương pháp thực hành giúp người đọc thay đổi thói quen suy nghĩ, từ đó sống vui vẻ và hiệu quả hơn mỗi ngày.','http://res.cloudinary.com/dqiefayjh/image/upload/v1774690505/books/j5elbps5ckx7d1fgfrfn.jpg',1948,'978-604-77-1541-8','NXB Tổng Hợp TP.HCM','Tiếng Việt','Bìa mềm',0,'quang-ganh-lo-di-ma-vui-song',85000.00,0),(18,'Vũ Trụ Trong Vỏ Hạt Dẻ ',67,6,120000.00,50,'Vũ Trụ Trong Vỏ Hạt Dẻ là một trong những tác phẩm khoa học nổi bật của Stephen Hawking, giúp người đọc tiếp cận những khái niệm phức tạp về vũ trụ theo cách đơn giản và dễ hiểu. Cuốn sách trình bày các lý thuyết hiện đại về không gian, thời gian, lỗ đen và nguồn gốc của vũ trụ, dựa trên những nghiên cứu tiên tiến trong vật lý.\r\n\r\nVới cách viết sinh động, kết hợp giữa khoa học và hình ảnh minh họa, cuốn sách không chỉ mang tính học thuật mà còn rất cuốn hút với người đọc phổ thông. Đây là lựa chọn tuyệt vời cho những ai yêu thích khám phá vũ trụ và muốn hiểu thêm về những bí ẩn của thế giới xung quanh.','http://res.cloudinary.com/dqiefayjh/image/upload/v1774690525/books/zddbnfepxxm2mkyugmsc.jpg',2001,'978-604-77-3654-3','NXB Trẻ','Tiếng Việt','Bìa cứng',0,'vu-tru-trong-vo-hat-de',120000.00,0),(19,'Gen Vị Kỷ',12,1,200000.00,20,'Gen Vị Kỷ là một trong những cuốn sách khoa học nổi bật về sinh học tiến hóa, trong đó Richard Dawkins đưa ra góc nhìn mới về cách sự sống phát triển. Thay vì xem sinh vật là trung tâm, tác giả cho rằng gen mới chính là yếu tố quyết định, và mọi hành vi của sinh vật đều nhằm mục đích duy trì và truyền lại gen.\r\n\r\nCuốn sách giải thích các khái niệm phức tạp bằng ngôn ngữ dễ hiểu, giúp người đọc tiếp cận khoa học một cách thú vị. Đây là tác phẩm có ảnh hưởng lớn, không chỉ trong lĩnh vực sinh học mà còn thay đổi cách con người nhìn nhận về sự sống và tiến hóa.','http://res.cloudinary.com/dqiefayjh/image/upload/v1774690545/books/aotdrurybootuy7rc2na.webp',1976,'978-604-77-3721-2','NXB Tri Thức','Tiếng Việt','Bìa mềm',0,'gen-vi-ky',250000.00,0),(20,'Còn chút gì để nhớ',1,1,75000.00,25,'“Còn chút gì để nhớ” là một trong những tác phẩm nhẹ nhàng và đầy hoài niệm của nhà văn Nguyễn Nhật Ánh. Câu chuyện xoay quanh nhân vật Chương, một chàng trai từ vùng quê nghèo bước chân vào Sài Gòn để học đại học, mang theo những bỡ ngỡ, rụt rè của một người trẻ trước sự phồn hoa đô hội. Tại đây, anh đã gặp gỡ và có những kỷ niệm đẹp đẽ, xen lẫn những tiếc nuối tuổi trẻ với các nhân vật như Quỳnh, Trâm, và gia đình họ. Qua ngòi bút tinh tế, chân thực, tác giả tái hiện lại không gian Sài Gòn những năm trước đổi mới với những nét văn hóa đặc trưng, những con đường rợp bóng cây và những mối quan hệ người với người dung dị, ấm áp. Mối tình đầu giữa Chương và Quỳnh chớm nở một cách tự nhiên nhưng cũng đầy e ấp, để rồi theo dòng thời gian và những biến động của cuộc sống, nó trở thành một vết cắt sâu thẳm trong lòng người ở lại. Tác phẩm không chỉ kể về tình yêu đôi lứa mà sâu sắc hơn, đó là câu chuyện về quá trình trưởng thành, về sự lựa chọn và những mất mát mà mỗi người phải trải qua khi bước vào đời. Kết thúc của truyện để lại trong lòng độc giả một nỗi buồn man mác, một sự nuối tiếc khôn nguôi về những gì đã qua, đúng như tên gọi của tác phẩm: tất cả giờ đây chỉ còn là chút gì để nhớ, để thương và để hoài niệm về một thời thanh xuân tươi đẹp nhưng đã mãi mãi lùi xa vào quá khứ.','http://res.cloudinary.com/dqiefayjh/image/upload/v1780666262/books/sxpxavkc7qki3wvuhpya.jpg',1988,'9786042168510','NXB Trẻ','Tiếng Việt','Bìa mềm',0,'con-chut-gi-de-nho',75000.00,0),(21,'Bàn có năm chỗ ngồi',1,1,68000.00,30,'“Bàn có năm chỗ ngồi” là tác phẩm truyện dài dành cho lứa tuổi học trò của nhà văn Nguyễn Nhật Ánh, xuất bản lần đầu vào năm 1985. Cuốn sách kể về một nhóm bạn gồm năm học sinh: Huy, Hiền, Khanh, Bảy và Quang, cùng ngồi chung một chiếc bàn học trong lớp. Mỗi nhân vật được xây dựng với một nét tính cách, hoàn cảnh gia đình và những ưu khuyết điểm hoàn toàn khác nhau. Huy là một lớp trưởng gương mẫu, học giỏi nhưng đôi khi còn cứng nhắc; Hiền dịu dàng, chu đáo; Khanh tinh nghịch, thông minh; Bảy hiền lành, thật thà và Quang là một học sinh cá biệt, ngỗ ngược nhưng ẩn sâu bên trong lại là một tâm hồn nhạy cảm và hoàn cảnh gia đình gặp nhiều khó khăn. Từ những bất đồng, hiểu lầm ban đầu trong học tập và sinh hoạt, nhóm bạn năm người đã dần thấu hiểu, chia sẻ và giúp đỡ lẫn nhau cùng tiến bộ. Tác phẩm làm nổi bật giá trị của tình bạn trong sáng, tinh thần đoàn kết và lòng nhân ái của tuổi học trò. Nguyễn Nhật Ánh đã rất thành công trong việc miêu tả tâm lý nhân vật một cách chân thực, sinh động, biến những bài học đạo đức giáo dục khô khan thành những câu chuyện gần gũi, cảm động, khơi gợi lòng trắc ẩn và trách nhiệm của mỗi cá nhân đối với tập thể và bạn bè xung quanh.','http://res.cloudinary.com/dqiefayjh/image/upload/v1780666275/books/meuisuqqpee1fix4zkdz.jpg',1987,'9786042168527','NXB Trẻ','Tiếng Việt','Bìa mềm',0,'ban-co-nam-cho-ngoi',68000.00,0),(22,'Bồ câu không đưa thư',1,1,72000.00,20,'“Bồ câu không đưa thư” là một tác phẩm vô cùng nổi tiếng nằm trong loạt truyện viết về bộ ba nữ sinh Xuyến, Thục, Cúc Hương của nhà văn Nguyễn Nhật Ánh. Câu chuyện bắt đầu từ một lá thư làm quen bí ẩn được giấu trong hộc bàn lớp học, ký tên là “Phong Linh”. Sự tò mò của tuổi học trò, đặc biệt là tính cách láu lỉnh của Xuyến, sự mơ mộng của Thục và tính thực tế của Cúc Hương đã cuốn ba cô gái vào một cuộc truy tìm danh tính người gửi thư đầy kịch tính và hài hước. Những hiểu lầm dở khóc dở cười liên tiếp xảy ra với các nam sinh trong lớp như Phán củi, Hòa, Thọ... tạo nên không khí vui tươi, nhộn nhịp đặc trưng của lứa tuổi học trò. Tuy nhiên, đằng sau những trò đùa tinh nghịch đó, tác phẩm dần mở ra những góc khuất cảm động về hoàn cảnh gia đình và nghị lực vươn lên của những người bạn cùng trang lứa. Tình bạn, tình thầy trò và những rung động đầu đời được thể hiện một cách trong sáng, tinh tế. Cuốn sách không chỉ mang lại tiếng cười mà còn để lại những bài học sâu sắc về sự đồng cảm, sẻ chia và tấm lòng trân trọng những giá trị chân thành trong cuộc sống, khiến người đọc nhớ về thời đi học với tất cả sự trân quý.','http://res.cloudinary.com/dqiefayjh/image/upload/v1780666300/books/xfeniyvhh1t6xjd5beif.jpg',1993,'9786042168534','NXB Trẻ','Tiếng Việt','Bìa mềm',0,'bo-cau-khong-dua-thu',72000.00,0),(23,'Chuyện hoa hồng',1,1,80000.00,15,'“Chuyện hoa hồng” của nhà văn Nguyễn Nhật Ánh là một câu chuyện tình yêu tuổi học trò đầy lãng mạn, dễ thương nhưng cũng không kém phần rắc rối. Nhân vật chính là Hòa, một chàng trai đem lòng cảm mến cô bạn học tên Hồng. Để tiếp cận và bày tỏ tình cảm của mình, Hòa đã nghĩ ra nhiều kế hoạch độc đáo, trong đó có việc mượn hình tượng hoa hồng để gửi gắm những thông điệp yêu thương thầm kín. Tác phẩm tái hiện một cách sinh động không khí lớp học với những trò đùa tinh nghịch, những người bạn hiến kế “quân sư quạt mo” vừa nhiệt tình vừa vụng về, gây ra những tình huống dở khóc dở cười. Qua ngòi bút dí dỏm và am hiểu tâm lý giới trẻ của tác giả, người đọc như được sống lại những giây phút hồi hộp, lo âu, vui sướng của mối tình đầu trong sáng. Sách không đặt nặng những triết lý đao to búa lớn mà tập trung khai thác những chuyển biến tinh tế trong cảm xúc của các nhân vật, từ sự ngại ngùng ban đầu đến sự thấu hiểu và trân trọng lẫn nhau, khẳng định vẻ đẹp vĩnh cửu của tình bạn và những tình cảm thuần khiết thời thanh xuân.',NULL,1989,'9786042168541','NXB Trẻ','Tiếng Việt','Bìa mềm',0,'chuyen-hoa-hong',80000.00,1),(24,'Lá nằm trong lá',1,1,95000.00,18,'“Lá nằm trong lá” là một tác phẩm truyện dài đặc sắc của Nguyễn Nhật Ánh, đưa người đọc quay trở lại với không gian học đường đầy kỷ niệm và mộng mơ của một nhóm bạn đam mê văn chương. Nhân vật chính cùng các bạn của mình đã thành lập một thi văn đoàn có tên là “Bút non”, cùng nhau sáng tác thơ ca, chia sẻ những suy nghĩ về cuộc sống và thể hiện cái tôi của tuổi mới lớn. Tác phẩm không chỉ xoay quanh những bài thơ học trò ngây ngô nhưng tràn đầy cảm xúc, mà còn khắc họa sâu sắc những mối quan hệ tình cảm gia đình, bạn bè và những rung động đầu đời nhẹ nhàng, kín đáo. Với giọng văn hóm hỉnh, giàu chất thơ và khả năng khắc họa tâm lý nhân vật tài tình, Nguyễn Nhật Ánh đã làm sống dậy một thời học sinh đầy nhiệt huyết, hoài bão nhưng cũng có những nỗi buồn, sự hiểu lầm nhỏ nhặt. “Lá nằm trong lá” như một lời nhắc nhở nhẹ nhàng về sự lưu giữ những kỷ niệm đẹp đẽ của tuổi trẻ, giúp con người có thêm sức mạnh và niềm tin khi vững bước vào tương lai.','http://res.cloudinary.com/dqiefayjh/image/upload/v1780666316/books/vjsinndtrsgqphpkqw84.jpg',2011,'9786042168558','NXB Trẻ','Tiếng Việt','Bìa mềm',0,'la-nam-trong-la',95000.00,0),(25,'Trăng nhảy cửa sổ',1,1,70000.00,22,'“Trăng nhảy cửa sổ” là một tác phẩm truyện dài dành cho thiếu nhi và tuổi mới lớn của nhà văn Nguyễn Nhật Ánh. Truyện kể về những cuộc phiêu lưu, những trò chơi tinh nghịch và cả những suy nghĩ non nớt nhưng đầy tình cảm của một nhóm trẻ em ở vùng quê. Hình ảnh ánh trăng “nhảy” qua cửa sổ vừa mang tính biểu tượng cho sự tự do, trí tưởng tượng phong phú của trẻ thơ, vừa là chứng nhân cho những câu chuyện bí mật, những ước mơ và hoài bão của các nhân vật nhỏ tuổi. Qua tác phẩm này, tác giả vẽ nên một bức tranh làng quê Việt Nam thanh bình, yên ả với những đêm trăng sáng, những cánh đồng lộng gió và những trò chơi dân gian quen thuộc. Cuốn sách ca ngợi tình bạn trong sáng, lòng hiếu thảo, sự sẻ chia giữa những đứa trẻ có hoàn cảnh khác nhau. Bằng lối kể chuyện tự nhiên, lôi cuốn và ngôn từ giản dị, tác phẩm mang lại cho người đọc cảm giác bình yên, khơi gợi lại những ký ức tuổi thơ tươi đẹp mà đôi khi người lớn đã vô tình lãng quên trong cuộc sống hiện đại tất bật.','http://res.cloudinary.com/dqiefayjh/image/upload/v1780666329/books/cuxovkkzq08h5mwg21hl.jpg',1985,'9786042168565','NXB Trẻ','Tiếng Việt','Bìa mềm',0,'trang-nhay-cua-so',70000.00,0),(26,'Lão Hạc',10,8,45000.00,40,'“Lão Hạc” là một trong những truyện ngắn xuất sắc và tiêu cực nhất của nhà văn Nam Cao, đại diện tiêu biểu cho trào lưu văn học hiện thực phê phán Việt Nam trước Cách mạng tháng Tám. Tác phẩm khắc họa một cách chân thực và cảm động số phận bi thảm của người nông dân Việt Nam trong xã hội thực dân nửa phong kiến. Lão Hạc, một lão nông nghèo, vợ mất sớm, con trai vì không có tiền cưới vợ đã phẫn chí bỏ đi đồn điền cao su. Lão sống thui thủi một mình cùng con chó tên là cậu Vàng – kỷ vật duy nhất mà người con trai để lại. Vì hoàn cảnh nghèo đói, dịch bệnh và muốn giữ lại mảnh vườn cho con, lão đã phải đau đớn bán đi cậu Vàng và cuối cùng chọn cái chết dữ dội bằng bả chó để bảo toàn lòng tự trọng và tài sản cho con. Qua nhân vật ông giáo – người kể chuyện, tác phẩm không chỉ phơi bày hiện thực tàn khốc, đẩy con người vào đường cùng mà còn ngợi ca vẻ đẹp tâm hồn cao quý, lòng nhân hậu, sự hy sinh thầm lặng và lòng tự trọng ngời sáng của người nông dân trong hoàn cảnh khốn cùng nhất.','http://res.cloudinary.com/dqiefayjh/image/upload/v1780564500/books/v6qr9qsnoasbfvylidcj.jpg',1943,'9786043331234','NXB Văn Học','Tiếng Việt','Bìa mềm',0,'lao-hac',45000.00,0),(27,'Sống mòn',10,8,85000.00,15,'“Sống mòn” (tên gốc là Chết mòn) là cuốn tiểu thuyết duy nhất và là đỉnh cao trong sự nghiệp sáng tác của nhà văn Nam Cao. Tác phẩm xoay quanh cuộc sống của Thứ, một trí thức tiểu tư sản nghèo làm nghề dạy học tại một trường tư thục ở ngoại ô Hà Nội trước năm 1945. Qua nhân vật Thứ cùng các đồng nghiệp như San, Oanh, tác phẩm đã phản ánh một cách sâu sắc bi kịch của tầng lớp trí thức nghèo trong xã hội cũ: họ có lý tưởng, có hoài bão, muốn sống một cuộc đời có ích và có ý nghĩa, nhưng lại bị gánh nặng của cơm áo gạo tiền, sự ích kỷ, nhỏ nhen của cuộc sống mưu sinh hằng ngày ghì chặt, bào mòn cả thể xác lẫn tâm hồn. Họ phải sống một cuộc sống đơn điệu, quẩn quanh, vô vị – một kiểu “chết mòn” khi đang sống. Nam Cao đã thể hiện một biệt tài phân tích tâm lý nhân vật sắc sảo, đi sâu vào những dằn vặt nội tâm, những cuộc đấu tranh giữa phần “người” cao khiết và những toan tính đời thường thấp hèn, từ đó đưa ra lời cảnh tỉnh sâu sắc về nguy cơ tha hóa của con người trước hoàn cảnh.','http://res.cloudinary.com/dqiefayjh/image/upload/v1780668307/books/ujxnsbuwxlsclgc3k0p7.jpg',1944,'9786043331258','NXB Văn Học','Tiếng Việt','Bìa mềm',0,'song-mon',85000.00,0),(28,'Đời thừa',10,8,48000.00,25,'“Đời thừa” là một truyện ngắn đặc sắc của Nam Cao viết về đề tài người trí thức trước Cách mạng. Nhân vật chính là Hộ, một nhà văn trẻ đầy tài năng, có hoài bão lớn lao là viết được một tác phẩm văn chương kiệt tác mang giá trị nhân đạo sâu sắc, có thể làm thay đổi con người và xã hội. Hộ cũng là một người có lòng nhân đạo cao cả khi anh sẵn sàng cưu mang Điền – một người phụ nữ bị ruồng rẫy cùng đứa con nhỏ. Thế nhưng, gánh nặng cơm áo gạo tiền của một gia đình đông con đã kéo Hộ xuống thực tại phũ phàng. Để có tiền nuôi vợ con, anh phải viết vội vàng, viết những cuốn sách rẻ tiền, “nhai lại” chính mình, điều mà anh coi là sự khốn nạn trong nghề văn. Bi kịch của Hộ càng đẩy lên đỉnh điểm khi anh tìm đến rượu để giải sầu rồi quay sang vũ phu, ngược đãi người vợ mà mình hằng thương yêu. Tác phẩm là tiếng kêu đau đớn về bi kịch tinh thần của người nghệ sĩ chân chính khi bị rơi vào cảnh “đời thừa”, đồng thời khẳng định một nguyên lý nghệ thuật và nhân sinh sâu sắc của Nam Cao: Một tác phẩm nghệ thuật chân chính phải vượt lên trên tất cả các bờ cõi và giới hạn, phải là một tác phẩm chung cho cả loài người.','http://res.cloudinary.com/dqiefayjh/image/upload/v1780668321/books/lgnievpaijws86jdlpw0.jpg',1943,'9786043331265','NXB Văn Học','Tiếng Việt','Bìa mềm',0,'doi-thua',48000.00,0),(29,'Truyện Tây Bắc',9,8,69000.00,19,'“Truyện Tây Bắc” là tập truyện ngắn nổi tiếng của nhà văn Tô Hoài, kết quả của chuyến đi thực tế dài ngày cùng bộ đội vào giải phóng Tây Bắc năm 1952. Tập truyện gồm ba tác phẩm: Mường Giơn, Cứu đất cứu mường và nổi bật nhất là Vợ chồng A Phủ. Tác phẩm tái hiện một cách sinh động, chân thực bức tranh thiên nhiên Tây Bắc hùng vĩ, thơ mộng nhưng cũng đầy khắc nghiệt, cùng cuộc sống đau khổ, tủi nhục của đồng bào các dân tộc thiểu số dưới ách áp bức độc ác của các chúa đất phong kiến và thực dân Pháp. Qua nhân vật Mỵ và A Phủ, Tô Hoài đã miêu tả sâu sắc quá trình thức tỉnh từ thân phận nô lệ chịu đựng, nhẫn nhục đến khát vọng sống, khát vọng tự do mạnh mẽ và con đường đứng lên cầm vũ khí đi theo cách mạng để tự giải phóng cuộc đời mình. Với ngôn ngữ giàu tính tạo hình, đượm màu sắc văn hóa Tây Bắc và tấm lòng nhân đạo sâu sắc, tác phẩm là một bài ca về sức sống tiềm tàng của con người và tình đoàn kết chiến đấu của các dân tộc Việt Nam.','http://res.cloudinary.com/dqiefayjh/image/upload/v1780668332/books/agxlyml5xqdqgxnzgidn.jpg',1953,'9786042169999','NXB Kim Đồng','Tiếng Việt','Bìa mềm',0,'truyen-tay-bac',69000.00,0),(30,'Vòng xoay tiền bạc (Cashflow Quadrant)',2,3,135000.00,35,'“Vòng xoay tiền bạc” (Cashflow Quadrant) – hay còn được biết đến với tên gọi “Dạy con làm giàu Tập 2” của tác giả Robert T. Kiyosaki, là một trong những cuốn sách kinh điển về tư duy tài chính cá nhân. Trong cuốn sách này, tác giả giới thiệu khái niệm mang tính cách mạng: Kim tứ đồ (The Cashflow Quadrant), chia những người tạo ra tiền bạc trong xã hội thành 4 nhóm rõ rệt dựa trên nguồn gốc thu nhập của họ: E (Employee - Người làm công ăn lương), S (Self-employed - Người làm tư, chủ doanh nghiệp nhỏ), B (Business owner - Chủ doanh nghiệp lớn), và I (Investor - Nhà đầu tư). Kiyosaki phân tích sâu sắc sự khác biệt cốt lõi về tư duy, giá trị sống và mức độ chấp nhận rủi ro giữa hai nửa của Kim tứ đồ. Trong khi nhóm bên trái (E và S) tìm kiếm sự ổn định, an toàn nhưng lại bị ràng buộc bởi thời gian và thuế suất cao, thì nhóm bên phải (B và I) lại hướng tới sự tự do tài chính bằng cách bắt tiền bạc và hệ thống làm việc cho mình. Cuốn sách định hướng và vạch ra con đường rõ ràng giúp độc giả thay đổi tư duy, từng bước chuyển dịch từ phía bên trái sang phía bên phải của Kim tứ đồ để đạt được sự độc lập và tự do tài chính đích thực.',NULL,2000,'9786041123456','NXB Trẻ','Tiếng Việt','Bìa mềm',0,'vong-xoay-tien-bac',135000.00,1),(31,'Hướng dẫn đầu tư',2,3,150000.00,20,'“Hướng dẫn đầu tư” (Dạy con làm giàu Tập 3) của Robert T. Kiyosaki là cuốn cẩm nang chuyên sâu dành cho những ai muốn thấu hiểu thế giới đầu tư tài chính từ góc nhìn của một người giàu. Tác giả không đưa ra những công thức làm giàu nhanh chóng hay những lời khuyên mua cổ phiếu cụ thể, mà tập trung vào việc xây dựng cấu trúc tư duy và triết lý đầu tư dài hạn. Cuốn sách giải thích các quy tắc đầu tư của người cha giàu, phân loại các kiểu nhà đầu tư khác nhau trong xã hội (từ nhà đầu tư đủ điều kiện, nhà đầu tư chuyên nghiệp đến nhà đầu tư thực sự) và những yêu cầu về kiến thức tài chính đi kèm. Kiyosaki nhấn mạnh tầm quan trọng của việc hiểu rõ các báo cáo tài chính, kiểm soát cảm xúc, và đặc biệt là kỹ năng xây dựng một doanh nghiệp vững mạnh trước khi bắt đầu đầu tư số tiền lớn. Đây là tài liệu nền tảng giúp người đọc phân biệt giữa đầu tư mạo hiểm vô căn cứ và đầu tư có tính toán, từ đó giảm thiểu rủi ro và tối đa hóa lợi nhuận trên con đường tìm kiếm tự do tài chính.','http://res.cloudinary.com/dqiefayjh/image/upload/v1780668345/books/n1p0fl9cus46zaingifg.jpg',2000,'9786041123463','NXB Trẻ','Tiếng Việt','Bìa mềm',0,'huong-dan-dau-tu',150000.00,0),(32,'Để có sức mạnh tài chính',2,3,115000.00,28,'“Để có sức mạnh tài chính” là một chương quan trọng trong loạt sách giáo dục tài chính của Robert T. Kiyosaki. Cuốn sách tập trung vào việc giải thích cách thức tạo ra và quản lý “sức mạnh đòn bẩy” trong tài chính cá nhân và doanh nghiệp. Tác giả chỉ ra rằng người giàu không chỉ làm việc chăm chỉ, mà họ biết cách sử dụng đòn bẩy bao gồm: tiền của người khác (OPM), thời gian của người khác (OPT), và các công cụ công nghệ, hệ thống để nhân bản tài sản của mình. Cuốn sách khuyến khích người đọc nâng cao “IQ tài chính” thông qua việc học hỏi về luật pháp, thuế, và cách thức vận hành của thị trường. Thay vì sợ hãi nợ nần, tác giả hướng dẫn cách phân biệt giữa “nợ tốt” (khoản nợ giúp tạo ra dòng tiền dương) và “nợ xấu” (khoản nợ lấy tiền ra khỏi túi bạn). Với những ví dụ thực tế và lập luận sắc bén, tác phẩm truyền cảm hứng mạnh mẽ để người đọc bứt phá khỏi những rào cản tư duy cũ kỹ, tự tin làm chủ vận mệnh tài chính của bản thân.','http://res.cloudinary.com/dqiefayjh/image/upload/v1780668536/books/usebtuho2kj0lfdyxiw0.jpg',2001,'9786041123470','NXB Trẻ','Tiếng Việt','Bìa mềm',0,'de-co-suc-manh-tai-chinh',115000.00,0),(33,'Nghệ thuật làm giàu',4,3,98000.00,30,'“Nghệ thuật làm giàu” là một cuốn sách tổng hợp các triết lý và phương pháp quản lý tài chính kinh điển, giúp người đọc thiết lập một mối quan hệ lành mạnh và thịnh vượng với tiền bạc. Sách đi sâu vào việc phân tích tâm lý học hành vi đối với tiền, giải thích lý do tại sao nhiều người dù kiếm được rất nhiều tiền vẫn rơi vào cảnh nợ nần, quẫn bách, trong khi những người có thu nhập trung bình lại có thể tích lũy được khối tài sản lớn. Tác giả trình bày các nguyên tắc cốt lõi như: tích lũy tối thiểu 10% thu nhập, đầu tư vào những lĩnh vực mình am hiểu, kiểm soát chi tiêu, và đa dạng hóa nguồn thu nhập để phòng ngừa rủi ro. Không dừng lại ở khía cạnh kỹ thuật, cuốn sách còn nhấn mạnh giá trị của sự kiên trì, kỷ luật bản thân và lòng biết ơn. Đây được coi là một kim chỉ nam tinh thần và thực tiễn, giúp độc giả từng bước xây dựng nền tảng tài chính vững chắc và bền vững theo thời gian.',NULL,1953,'9786049511111','NXB Tổng Hợp','Tiếng Việt','Bìa mềm',0,'nghe-thuat-lam-giau',98000.00,1),(34,'Chìa khóa tư duy thành công',4,3,90000.00,25,'“Chìa khóa tư duy thành công” là tác phẩm đúc kết những nguyên tắc vàng trong việc phát triển bản thân và định hình tư duy của những người thành đạt nhất trên thế giới. Cuốn sách khẳng định một chân lý: Thành công hay thất bại không phụ thuộc vào may mắn hay hoàn cảnh xuất thân, mà phụ thuộc hoàn toàn vào cách chúng ta tư duy và phản ứng trước các tình huống trong cuộc sống. Tác giả hướng dẫn người đọc cách thiết lập mục tiêu rõ ràng, cụ thể và có thể đo lường được; cách vượt qua nỗi sợ hãi thất bại và biến nghịch cảnh thành cơ hội học hỏi. Sách cũng nhấn mạnh đến sức mạnh của thói quen tích cực, việc quản lý năng lượng bản thân và tầm quan trọng của việc xây dựng các mối quan hệ chất lượng. Bằng những câu chuyện truyền cảm hứng và các bài tập thực hành cụ thể, cuốn sách là chìa khóa mở ra cánh cửa khai phá tiềm năng vô hạn ẩn giấu trong mỗi con người, giúp họ đạt được thành tựu đột phá trong cả sự nghiệp lẫn cuộc sống.',NULL,1945,'9786049511128','NXB Tổng Hợp','Tiếng Việt','Bìa mềm',0,'chia-khoa-tu-duy-thanh-cong',90000.00,1),(35,'Nghệ thuật nói trước công chúng',3,4,88000.00,42,'“Nghệ thuật nói trước công chúng” (thường gắn liền với các triết lý của Dale Carnegie) là cuốn cẩm nang toàn diện giúp người đọc vượt qua nỗi sợ hãi lớn nhất của con người: nói trước đám đông. Cuốn sách không chỉ dạy về các kỹ thuật điều khiển giọng nói, ngôn ngữ cơ thể hay cách biên soạn một bài thuyết trình logic, mà quan trọng hơn, nó tập trung vào việc xây dựng sự tự tin từ bên trong nội tâm người nói. Tác giả chỉ ra rằng, để lôi cuốn người nghe, người nói phải thực sự thấu hiểu thính giả của mình, nói bằng sự chân thành, nhiệt huyết và chuẩn bị nội dung thật kỹ lưỡng. Sách cung cấp các mẹo thực tế để mở đầu bài nói ấn tượng, cách xử lý các tình huống bất ngờ trên sân khấu, và cách kết thúc để lại ấn tượng sâu đậm. Đây là cuốn sách gối đầu giường không thể thiếu cho các nhà lãnh đạo, nhà quản lý, học sinh sinh viên và bất kỳ ai muốn nâng cao năng lực giao tiếp, thuyết phục và truyền cảm hứng trong công việc và cuộc sống.','http://res.cloudinary.com/dqiefayjh/image/upload/v1780668546/books/tzgr97k2d88mdrjergcu.jpg',1926,'9786045678912','NXB Tổng Hợp','Tiếng Việt','Bìa mềm',0,'nghe-thuat-noi-truoc-cong-chung',88000.00,0),(36,'Bí quyết thành công',3,4,82000.00,50,'“Bí quyết thành công” là một tác phẩm mang tính tổng hợp cao, đúc kết những bài học xương máu của nhiều thế hệ doanh nhân và nhà tư tưởng vĩ đại. Cuốn sách tập trung vào việc phân tích các yếu tố quyết định tạo nên sự thành đạt lâu dài, bao gồm: khát vọng mãnh liệt, sự kiên trì bền bỉ, khả năng thích ứng nhanh chóng với sự thay đổi của môi trường, và đạo đức nghề nghiệp chính trực. Tác giả chia sẻ các phương pháp quản lý thời gian hiệu quả, kỹ năng ra quyết định trong những thời điểm khủng hoảng và nghệ thuật ủy quyền, phối hợp làm việc nhóm. Điểm đặc biệt của cuốn sách là nó không cổ súy cho sự thành công bằng mọi giá, mà luôn hướng con người tới sự cân bằng giữa công việc, gia đình và sức khỏe tinh thần. Đây là một nguồn động lực to lớn, tiếp thêm sức mạnh và niềm tin cho người đọc, đặc biệt là những người trẻ đang trên con đường lập thân, lập nghiệp.',NULL,1932,'9786045678929','NXB Tổng Hợp','Tiếng Việt','Bìa mềm',0,'bi-quyet-thanh-cong',82000.00,1),(37,'21 bài học cho thế kỷ 21',5,5,165000.00,15,'“21 bài học cho thế kỷ 21” là tác phẩm ăn khách của nhà sử học nổi tiếng Yuval Noah Harari. Sau khi nhìn về quá khứ trong Sapiens và dự phóng tương lai trong Homo Deus, Harari quay trở lại với những vấn đề cấp bách nhất của hiện tại. Cuốn sách được chia thành 21 chương, thảo luận về các chủ đề đa dạng từ thách thức công nghệ (trí tuệ nhân tạo, công nghệ sinh học làm thay đổi thị trường lao động và định nghĩa về con người), khủng hoảng chính trị (sự suy thoái của chủ nghĩa tự do, chủ nghĩa dân tộc cực đoan), cho đến các vấn đề văn hóa, tôn giáo và giáo dục. Harari không đưa ra những câu trả lời giản đơn, mà kích thích người đọc suy nghĩ sâu sắc về cách định vị bản thân trong một thế giới tràn ngập tin giả, sự bất định và biến đổi không ngừng. Tác phẩm là một lời cảnh tỉnh mạnh mẽ, đồng thời là lời hướng dẫn tư duy giúp nhân loại chuẩn bị tâm thế đối mặt với những biến động lịch sử vô tiền khoáng hậu đang diễn ra.','http://res.cloudinary.com/dqiefayjh/image/upload/v1780666832/books/ektpcqgqhlxwoorloclz.jpg',2018,'9786041145678','NXB Thế Giới','Tiếng Việt','Bìa mềm',0,'21-bai-hoc-cho-the-ky-21',165000.00,0),(38,'Lược sử thời gian',67,6,115000.00,38,'“Lược sử thời gian” (A Brief History of Time) là cuốn sách khoa học phổ thông kiệt tác của nhà vật lý lý thuyết vĩ đại Stephen Hawking. Xuất bản lần đầu năm 1988, cuốn sách nhanh chóng trở thành một hiện tượng toàn cầu, giúp những khái niệm vật lý thiên văn học cực kỳ phức tạp trở nên gần gũi với công chúng. Trong cuốn sách này, Hawking dẫn dắt người đọc vào một cuộc hành trình khám phá nguồn gốc, cấu trúc, sự hình thành và số phận cuối cùng của vũ trụ. Ông giải thích các lý thuyết nền tảng của vật lý hiện đại như Thuyết tương đối tổng quát của Einstein, Cơ học lượng tử, sự giãn nở của vũ trụ, Vụ nổ lớn (Big Bang) và bản chất bí ẩn của Lỗ đen. Mục tiêu tối thượng của Hawking khi viết cuốn sách là tìm kiếm một “Lý thuyết thống nhất hoàn chỉnh” (Theory of Everything) có thể dung hợp tất cả các quy luật của tự nhiên. Với lối viết giản dị, hạn chế tối đa các phương trình toán học phức tạp kết hợp với sự dí dỏm sâu sắc, tác phẩm khơi dậy niềm đam mê khoa học và sự ngưỡng mộ trước vẻ đẹp kỳ vĩ của vũ trụ.','http://res.cloudinary.com/dqiefayjh/image/upload/v1780666820/books/ypblejlhjtpfvdydbufu.jpg',1988,'9786042123444','NXB Trẻ','Tiếng Việt','Bìa mềm',0,'luoc-su-thoi-gian',115000.00,0),(39,'Bản thiết kế vĩ đại',67,6,125000.00,20,'“Bản thiết kế vĩ đại” (The Grand Design) là tác phẩm khoa học xuất sắc được viết bởi Stephen Hawking và Leonard Mlodinow. Cuốn sách tiếp tục cuộc hành trình giải thích các bí ẩn lớn nhất của vũ trụ từ góc nhìn của vật lý hiện đại, đặc biệt là Thuyết M (M-theory) – ứng cử viên sáng giá nhất cho Lý thuyết thống nhất hoàn chỉnh. Các tác giả đặt ra và tìm cách trả lời ba câu hỏi cốt lõi: Tại sao lại có cái gì đó thay vì không có gì? Tại sao chúng ta lại tồn tại? Và tại sao tập hợp các quy luật tự nhiên này lại chính xác đến mức cho phép sự sống hình thành? Cuốn sách giới thiệu khái niệm “hiện thực phụ thuộc vào mô hình” (model-dependent realism), thách thức những quan niệm truyền thống về triết học và tôn giáo về sự sáng tạo thế giới. Bằng những lập luận khoa học sắc bén cùng hình ảnh minh họa sinh động, tác phẩm khẳng định vũ trụ có thể tự thiết lập và hình thành từ hư vô dựa trên các định luật vật lý mà không cần đến sự can thiệp của một đấng siêu nhiên.','http://res.cloudinary.com/dqiefayjh/image/upload/v1780666807/books/va3hzcsd5tzcqrtb9m7d.jpg',2010,'9786042123451','NXB Trẻ','Tiếng Việt','Bìa mềm',0,'ban-thiet-ke-vi-dai',125000.00,0),(40,'Mở rộng kiểu hình (The Extended Phenotype)',12,6,220000.00,10,'“Mở rộng kiểu hình” (The Extended Phenotype) là một tác phẩm khoa học chuyên sâu và mang tính đột phá của nhà sinh học tiến hóa Richard Dawkins, được xem là phần tiếp theo và phát triển nâng cao của cuốn sách nổi tiếng “Gen vị kỷ”. Trong tác phẩm này, Dawkins đưa ra một luận điểm cách mạng: tầm ảnh hưởng và biểu hiện của gen (kiểu hình) không chỉ giới hạn bên trong cơ thể sinh vật chứa đựng nó, mà có thể mở rộng ra môi trường bên ngoài, bao gồm cả các vật thể vô tri và các sinh vật khác. Ví dụ, chiếc đập của loài hải ly, chiếc tổ của loài kiến hay hành vi điều khiển vật chủ của ký sinh trùng đều được coi là một phần kiểu hình mở rộng của các gen tương ứng. Tác phẩm thách thức quan niệm truyền thống coi cá thể sinh vật là đơn vị duy nhất của chọn lọc tự nhiên, tái định hình cách nhìn nhận của giới khoa học về mối quan hệ giữa sinh vật và môi trường. Đây là cuốn sách có giá trị học thuật cao, đòi hỏi người đọc có nền tảng kiến thức sinh học nhất định nhưng mang lại một tư duy vô cùng mới mẻ về tiến hóa.','http://res.cloudinary.com/dqiefayjh/image/upload/v1780666787/books/qkywx1slgkut4bk2pkof.jpg',1982,'9786045699881','NXB Khoa Học Kỹ Thuật','Tiếng Anh','Bìa cứng',0,'mo-rong-kieu-hinh-the-extended-phenotype',220000.00,0),(41,'Chuyện người tùy tùng',6,7,85000.00,24,'“Chuyện người tùy tùng” (The Handmaid\'s Tale) của nữ văn sĩ Margaret Atwood là một cuốn tiểu thuyết viễn tưởng phản địa đàng (dystopian) kinh điển và gây tiếng vang lớn trên toàn thế giới. Câu chuyện lấy bối cảnh tại Cộng hòa Gilead – một chế độ độc tài thần quyền quân sự được thiết lập trên lãnh thổ nước Mỹ sau một cuộc đảo chính. Trong xã hội này, do thảm họa môi trường dẫn đến tỷ lệ sinh sản giảm mạnh, phụ nữ bị tước đoạt toàn bộ quyền công dân, quyền sở hữu tài sản và bị phân loại dựa trên chức năng sinh sản. Nhân vật chính, Offred, thuộc tầng lớp “Người tùy tùng” (Handmaid) – những người phụ nữ còn khả năng sinh sản bị ép buộc trở thành công cụ sinh con cho các gia đình quan chức cấp cao. Qua dòng hồi tưởng và góc nhìn nội tâm đầy đau đớn nhưng kiên cường của Offred, Atwood đã phơi bày sự tàn bạo của chế độ độc tài, sự kiểm soát cơ thể và tư tưởng con người, đồng thời tôn vinh khát vọng tự do, tình yêu và sức sống mãnh liệt của người phụ nữ trước sự áp bức tột cùng.',NULL,2010,'9786045331112','NXB Văn Học','Tiếng Việt','Bìa mềm',0,'chuyen-nguoi-tuy-tung',85000.00,1),(43,'Harry Potter và Phòng Chứa Bí Mật',8,7,130000.00,45,'“Harry Potter và Phòng Chứa Bí Mật” là tập truyện thứ hai trong loạt tiểu thuyết phù thủy lừng danh của nữ nhà văn J.K. Rowling. Trong năm học thứ hai tại Trường Phù thủy và Pháp sư Hogwarts, Harry Potter và các bạn của mình là Ron và Hermione phải đối mặt với một mối đe dọa cổ xưa và vô cùng nguy hiểm. Cánh cửa Phòng Chứa Bí Mật – nơi được đồn đại là do Salazar Slytherin xây dựng để thanh trừng những phù thủy không thuần chủng – đã bị mở ra bởi một kẻ kế vị bí ẩn. Hàng loạt vụ tấn công kinh hoàng bằng cách hóa đá các học sinh gốc Muggle xảy ra khiến trường học rơi vào tình trạng hoảng loạn và có nguy cơ phải đóng cửa. Harry liên tục nghe thấy những tiếng thì thầm ma quái bên trong các bức tường và bị nghi ngờ là kẻ phạm tội do có khả năng nói xà ngữ. Bằng lòng dũng cảm, sự thông minh và tình bạn gắn kết, bộ ba đã khám phá ra sự thật về cuốn nhật ký ký ức của Tom Riddle và tiêu diệt con quái vật Tử xà Basilik khổng lồ, cứu sống cô bé Ginny Weasley và lập lại hòa bình cho Hogwarts.','http://res.cloudinary.com/dqiefayjh/image/upload/v1780667087/books/q1sxtr6ajvbj9vkps3mg.jpg',1998,'9786042167773','NXB Trẻ','Tiếng Việt','Bìa mềm',0,'harry-potter-va-phong-chua-bi-mat',130000.00,0),(44,'Harry Potter và Tên Tù Nhân Ngục Azkaban',8,7,145000.00,40,'“Harry Potter và Tên Tù Nhân Ngục Azkaban” là tập thứ ba trong bộ sách Harry Potter của J.K. Rowling, đánh dấu sự chuyển mình mạnh mẽ trong cốt truyện sang một tông màu đen tối và trưởng thành hơn. Năm học thứ ba của Harry bắt đầu trong sự canh phòng nghiêm ngặt của các Giám ngục Azkaban (Dementors) xung quanh trường Hogwarts, bởi Sirius Black – một kẻ sát nhân hàng loạt khét tiếng và là tay sai đắc lực của Chúa tể Voldemort – vừa trốn thoát khỏi nhà tù phù thủy kiên cố nhất thế giới và được cho là đang săn lùng Harry. Tập truyện giới thiệu nhiều nhân vật và khái niệm quan trọng như Thầy Remus Lupin, Thần hộ mệnh (Patronus), Bản đồ Đạo tặc (Marauder\'s Map), và chiếc Xoay thời gian. Qua những nút thắt bất ngờ và đầy kịch tính, Harry phát hiện ra Sirius Black thực chất bị oan và chính là cha đỡ đầu yêu quý của mình, trong khi kẻ phản bội thực sự lại là Peter Pettigrew dưới lốt con chuột Scabbers. Tác phẩm ca ngợi tình bạn, lòng trung thành và hành trình vượt qua nỗi sợ hãi của bản thân.','http://res.cloudinary.com/dqiefayjh/image/upload/v1780667073/books/sft7gknhaxwqbohu3qpc.jpg',1999,'9786042167780','NXB Trẻ','Tiếng Việt','Bìa mềm',0,'harry-potter-va-ten-tu-nhan-nguc-azkaban',145000.00,0),(45,'Harry Potter và Chiếc Cốc Lửa',8,7,195000.00,35,'“Harry Potter và Chiếc Cốc Lửa” là bước ngoặt quan trọng trong toàn bộ loạt truyện của J.K. Rowling. Trong năm học thứ tư, Hogwarts vinh dự trở thành nước chủ nhà tổ chức Giải đấu Tam Pháp Thuật (Triwizard Tournament) – một cuộc thi pháp thuật cổ xưa đầy nguy hiểm giữa ba trường phù thủy hàng đầu châu Âu. Một cách bí ẩn và đầy bất ngờ, Chiếc Cốc Lửa đã chọn Harry Potter làm quán quân thứ tư, ép buộc cậu phải tham gia tranh tài dù chưa đủ tuổi. Harry phải vượt qua ba bài thi sinh tử: đối đầu với rồng đuôi gai, giải cứu người thân dưới lòng hồ sâu và vượt qua mê cung biến hóa đầy cạm bẫy. Tuy nhiên, toàn bộ giải đấu thực chất là một âm mưu thâm độc được sắp đặt bởi thuộc hạ của Voldemort. Ở cuối mê cung, Harry và người bạn Cedric Diggory bị dịch chuyển đến một nghĩa địa hoang vu, nơi chứng kiến sự hy sinh đau lòng của Cedric và sự hồi sinh chính thức bằng xương bằng thịt của Chúa tể Hắc ám Voldemort, mở ra một thời kỳ đen tối và chiến tranh toàn diện cho thế giới phù thủy.','http://res.cloudinary.com/dqiefayjh/image/upload/v1780667059/books/pnieeljpscnulzxr2sw6.jpg',2000,'9786042167797','NXB Trẻ','Tiếng Việt','Bìa mềm',0,'harry-potter-va-chiec-coc-lua',195000.00,0),(46,'Harry Potter và Mệnh Lệnh Phượng Hoàng',8,7,240000.00,30,'“Harry Potter và Mệnh Lệnh Phượng Hoàng” là tập truyện dài nhất trong loạt sách của J.K. Rowling, tập trung khai thác sâu sắc những diễn biến tâm lý phức tạp, sự cô độc và nổi loạn của tuổi dậy thì của Harry Potter. Sau sự trở lại của Voldemort, Bộ Pháp thuật chối bỏ sự thật và thực hiện chiến dịch bôi nhọ danh dự của Harry và Thầy Dumbledore. Bộ cử Dolores Umbridge – một người đàn bà tàn nhẫn, giáo điều – đến làm Giáo trưởng và sau đó là Hiệu trưởng Hogwarts, biến trường học thành một nhà tù với những quy định hà khắc. Trước tình hình đó, Harry đã thành lập “Quân đoàn Dumbledore” (D.A.) để bí mật dạy các bạn học phòng chống nghệ thuật hắc ám. Đồng thời, tổ chức bí mật “Mệnh Lệnh Phượng Hoàng” cũng được tái lập để chống lại các Tử thần Thực tử. Đỉnh điểm của tập truyện là trận chiến khốc liệt tại Bộ Pháp thuật, dẫn đến cái chết đau thương của Sirius Black, để lại trong lòng Harry một khoảng trống lớn và sự thức tỉnh về trách nhiệm nặng nề của một “người được chọn” thông qua lời tiên tri định mệnh.','http://res.cloudinary.com/dqiefayjh/image/upload/v1780667047/books/k05rcz9phddlwlzwxi2f.jpg',2003,'9786042167803','NXB Trẻ','Tiếng Việt','Bìa mềm',0,'harry-potter-va-menh-lenh-phuong-hoang',240000.00,0),(47,'Harry Potter và Hoàng Tử Lai',8,7,210000.00,32,'“Harry Potter và Hoàng Tử Lai” là tập thứ sáu trong loạt tiểu thuyết của J.K. Rowling, chuẩn bị tiền đề trực tiếp cho trận chiến cuối cùng. Khi thế giới phù thủy và cả thế giới Muggle rơi vào tình trạng chiến tranh l loạn do sự phá hoại của Voldemort, trường Hogwarts không còn là nơi an toàn tuyệt đối. Trong năm học này, Harry tìm thấy một cuốn sách giáo khoa Độc dược cũ thuộc sở hữu của một người tự xưng là “Hoàng tử Lai”, chứa đựng nhiều bùa chú tự chế hữu ích nhưng cũng đầy nguy hiểm. Thầy Dumbledore đã dành nhiều thời gian để dạy riêng cho Harry, sử dụng Tưởng ký để khám phá quá khứ của Tom Riddle, từ đó tìm ra bí mật về sự bất tử của hắn: các Trường Sinh Linh Giá (Horcruxes) – những vật thể chứa các mảnh linh hồn bị chia cắt của Voldemort. Mối quan hệ tình cảm tuổi học trò giữa Harry và Ginny, Ron và Hermione cũng có những chuyển biến rõ nét. Tác phẩm khép lại bằng một bi kịch gây sốc toàn cầu: Thầy Dumbledore bị sát hại bởi Severus Snape ngay trên tháp thiên văn, đẩy Hogwarts vào cảnh mất mát đau thương và buộc Harry phải đưa ra quyết định từ bỏ việc học để lên đường tìm kiếm và tiêu diệt các Trường Sinh Linh Giá.','http://res.cloudinary.com/dqiefayjh/image/upload/v1780667036/books/vfl0jnnjtef0nr9xkwy1.jpg',2005,'9786042167810','NXB Trẻ','Tiếng Việt','Bìa mềm',0,'harry-potter-va-hoang-tu-lai',210000.00,0),(48,'Harry Potter và Bảo Bối Tử Thần',8,7,260000.00,38,'Phần cuối cùng khép lại thiên sử thi về thế giới phù thủy. Bộ ba Harry, Ron, Hermione lên đường tìm kiếm và tiêu diệt các Trường Sinh Linh Giá còn lại.','http://res.cloudinary.com/dqiefayjh/image/upload/v1780667012/books/o5eqjyymf4itsz15vbl2.jpg',2007,'9786042167827','NXB Trẻ','Tiếng Việt','Bìa mềm',0,'harry-potter-va-bao-boi-tu-than',260000.00,0),(49,'Con đường hồi hương',6,7,78000.00,15,'Một câu chuyện sâu lắng khác của Paulo Coelho về việc chấp nhận những vết thương trong quá khứ để tìm thấy lối đi thanh thản cho tương lai.',NULL,2012,'9786045331136','NXB Văn Học','Tiếng Việt','Bìa mềm',0,'con-duong-hoi-huong',78000.00,1),(50,'Ảo tưởng Thượng đế (The God Delusion)',12,6,185000.00,15,'Một trong những cuốn sách gây tranh cãi và nổi tiếng nhất của Richard Dawkins, phân tích hiện tượng tôn giáo dưới góc nhìn khoa học hành vi và sinh học tiến hóa.','http://res.cloudinary.com/dqiefayjh/image/upload/v1780667302/books/pjx53spfsgpewdh3nh5h.jpg',2006,'9786045699898','NXB Khoa Học Kỹ Thuật','Tiếng Việt','Bìa mềm',0,'ao-tuong-thuong-de-the-god-delusion',185000.00,0),(51,'Nhà leo núi bất khả thi (Climbing Mount Improbable)',12,6,160000.00,20,'Dawkins sử dụng hình tượng một ngọn núi dốc đứng để giải thích cách mà cơ chế tiến hóa chọn lọc tự nhiên từng bước nhỏ tạo ra các cơ quan vô cùng phức tạp ở sinh vật.','http://res.cloudinary.com/dqiefayjh/image/upload/v1780667319/books/c7wlm19syrbmcghtdleq.jpg',1996,'9786045699904','NXB Khoa Học Kỹ Thuật','Tiếng Việt','Bìa mềm',0,'nha-leo-nui-bat-kha-thi-climbing-mount-improbable',160000.00,0),(52,'Sự trình diễn vĩ đại nhất Trái Đất (The Greatest Show on Earth)',12,6,210000.00,12,'“Sự trình diễn vĩ đại nhất Trái Đất” (The Greatest Show on Earth) của Richard Dawkins là một cuốn sách khoa học phổ thông xuất sắc, trình bày các bằng chứng không thể chối cãi về thuyết tiến hóa của Charles Darwin. Tác giả ví tiến hóa như một vở kịch vĩ đại đang diễn ra trên Trái Đất và đảm nhận vai trò một người hướng dẫn khoa học, đập tan những luận điệu sai lệch của chủ nghĩa sáng thế. Dawkins dẫn dắt người đọc qua hàng loạt các bằng chứng thực nghiệm mạnh mẽ: từ việc chọn lọc nhân tạo trong chăn nuôi và cây trồng; các bằng chứng hóa thạch ghi lại lịch sử địa chất; sự tương đồng về giải phẫu học và phôi thai học giữa các loài; cho đến những phát hiện đột phá của di truyền học hiện đại và sinh học phân tử về mã DNA chung của muôn loài. Với phong cách viết văn sắc bén, cuốn hút và tràn đầy nhiệt huyết khoa học, tác phẩm không chỉ chứng minh tính đúng đắn của tiến hóa như một sự thật khách quan, mà còn khơi dậy trong lòng người đọc niềm kính ngưỡng, say mê trước sự đa dạng, diệu kỳ và tinh tế của thế giới tự nhiên.','http://res.cloudinary.com/dqiefayjh/image/upload/v1780667330/books/olmmdwxylo8rzq3mwfrw.jpg',2009,'9786045699911','NXB Khoa Học Kỹ Thuật','Tiếng Việt','Bìa mềm',0,'su-trinh-dien-vi-dai-nhat-trai-dat-the-greatest-show-on-earth',210000.00,0),(53,'Gỡ rối cầu vồng (Unweaving the Rainbow)',12,6,145000.00,18,'“Gỡ rối cầu vồng” (Unweaving the Rainbow) là một tác phẩm mang tính triết học khoa học sâu sắc của Richard Dawkins. Tên cuốn sách bắt nguồn từ lời chỉ trích của nhà thơ John Keats dành cho Isaac Newton, cho rằng Newton đã làm mất đi vẻ đẹp huyền bí, lãng mạn của cầu vồng khi dùng lăng kính để phân tích nó thành các dải màu sắc quang phổ. Dawkins mạnh mẽ phản bác quan điểm này, khẳng định rằng khoa học không hề làm khô cằn hay hủy hoại thơ ca, mà ngược lại, sự hiểu biết thấu đáo về bản chất quy luật của tự nhiên chính là nguồn cảm hứng thơ ca vĩ đại và chân thực nhất. Việc thấu hiểu cầu vồng dẫn đến sự ra đời của ngành thiên văn quang phổ, cho phép con người biết được thành phần hóa học của những ngôi sao cách chúng ta hàng triệu năm ánh sáng. Cuốn sách là một lời ca ngợi trí tuệ con người, khuyến khích tư duy duy lý và phê phán các niềm tin mê tín dị đoan, chiêm tinh học hay thế giới tâm linh giả tạo, hướng con người tới việc tận hưởng vẻ đẹp đích thực của thực tại khách quan.',NULL,1998,'9786045699928','NXB Khoa Học Kỹ Thuật','Tiếng Việt','Bìa mềm',0,'go-roi-cau-vong',145000.00,1),(54,'Người thợ đồng hồ mù (The Blind Watchmaker)',12,6,175000.00,25,'“Người thợ đồng hồ mù” (The Blind Watchmaker) là một trong những tác phẩm quan trọng và nổi tiếng nhất của Richard Dawkins về triết học sinh học. Tác phẩm trực tiếp phản biện luận điểm nổi tiếng của nhà thần học William Paley ở thế kỷ 19: Paley cho rằng nếu ta tìm thấy một chiếc đồng hồ trên mặt đất với cấu tạo vô cùng tinh vi, ta phải thừa nhận có một người thợ đồng hồ thông minh đã chế tạo ra nó; tương tự, các sinh vật với cấu tạo cơ thể cực kỳ phức tạp và hoàn hảo chắc chắn phải do một Đấng Sáng Thế tối cao thiết kế. Dawkins đã chứng minh một cách xuất sắc rằng lực lượng duy nhất đứng sau sự phức tạp kỳ diệu đó chính là quá trình chọn lọc tự nhiên diễn ra trong hàng triệu năm. Chọn lọc tự nhiên không có mục đích, không có tầm nhìn tương lai, không có tâm trí – nó hoạt động một cách mù quáng, tự động nhưng lại có khả năng tạo ra những cấu trúc tinh vi vượt xa mọi công nghệ loài người. Sách là một bài học sâu sắc về tư duy hệ thống và lý thuyết tiến hóa hiện đại.','http://res.cloudinary.com/dqiefayjh/image/upload/v1780667483/books/hepmkzhj09oc5sefqgff.jpg',1986,'9786045699935','NXB Khoa Học Kỹ Thuật','Tiếng Việt','Bìa mềm',0,'nguoi-tho-dong-ho-mu-the-blind-watchmaker',175000.00,0),(55,'Trả lời ngắn gọn những câu hỏi lớn',67,6,135000.00,30,'“Trả lời ngắn gọn những câu hỏi lớn” (Brief Answers to the Big Questions) là cuốn sách cuối cùng của Stephen Hawking, được hoàn thiện và xuất bản sau khi ông qua đời vào năm 2018. Cuốn sách là sự đúc kết trí tuệ cả cuộc đời của nhà vật lý thiên văn vĩ đại trước những câu hỏi mang tính sống còn và triết học sâu sắc nhất của nhân loại. Sách được chia thành 10 chương, trả lời trực diện các câu hỏi như: Có Thượng đế không? Vũ trụ bắt đầu như thế nào? Có sự sống thông minh khác ngoài Trái Đất không? Chúng ta có thể dự đoán tương lai không? Bên trong lỗ đen có gì? Du hành thời gian có khả thi không? Chúng ta có nên định cư ngoài vũ trụ? Trí tuệ nhân tạo sẽ thông minh hơn chúng ta? Và làm thế nào để chúng ta định hình tương lai? Hawking đưa ra những câu trả lời dựa trên những thành tựu khoa học mới nhất với một tinh thần lạc quan, đầy trách nhiệm đối với tương lai của Trái Đất. Đây là một lời di chúc tinh thần vô giá, truyền cảm hứng cho thế hệ trẻ tiếp tục tò mò, khám phá và bảo vệ hành tinh xanh.','http://res.cloudinary.com/dqiefayjh/image/upload/v1780667674/books/zyqayzoorbepz0lvrva5.jpg',2018,'9786042123468','NXB Trẻ','Tiếng Việt','Bìa mềm',0,'tra-loi-ngan-gon-nhung-cau-hoi-lon',135000.00,0),(56,'Lược sử đời tôi (My Brief History)',67,6,95000.00,15,'Cuốn tự truyện chân thực và cảm động của Stephen Hawking, kể về hành trình từ một cậu học sinh bình thường đến nhà vật lý lý thuyết vĩ đại chiến đấu với căn bệnh ALS.','http://res.cloudinary.com/dqiefayjh/image/upload/v1780667684/books/fxhj1snkr756pmswod9t.jpg',2013,'9786042123475','NXB Trẻ','Tiếng Việt','Bìa mềm',0,'luoc-su-doi-toi-my-brief-history',95000.00,0),(57,'Trên vai những người khổng lồ (On the Shoulders of Giants)',67,6,290000.00,10,'Stephen Hawking tuyển chọn và phân tích các văn bản khoa học gốc vĩ đại nhất làm thay đổi lịch sử vật lý của Einstein, Newton, Galileo, Copernicus và Kepler.','http://res.cloudinary.com/dqiefayjh/image/upload/v1780667696/books/uximg7jqeeyvhv87k6uu.jpg',2002,'9786042123482','NXB Trẻ','Tiếng Việt','Bìa cứng',0,'tren-vai-nhung-nguoi-khong-lo-on-the-shoulders-of-giants',290000.00,0),(58,'Bản chất của Không gian và Thời gian',67,6,120000.00,22,'Ghi lại chuỗi các cuộc tranh luận học thuật đỉnh cao giữa Stephen Hawking và Roger Penrose về lý thuyết hấp dẫn lượng tử và bản chất của hố đen.',NULL,1996,'9786042123499','NXB Trẻ','Tiếng Việt','Bìa mềm',0,'ban-chat-cua-khong-gian-va-thoi-gian',120000.00,1),(59,'Lỗ đen và Vũ trụ sơ khai (Black Holes and Baby Universes)',67,6,110000.00,26,'Tập hợp các bài viết và bài giảng nổi bật của Hawking về hố đen, lý thuyết nhiệt động lực học vũ trụ và cách mà các vũ trụ con có thể được hình thành.','http://res.cloudinary.com/dqiefayjh/image/upload/v1780667707/books/kmlhjyh0aymaqxuacjbm.jpg',1993,'9786042123505','NXB Trẻ','Tiếng Việt','Bìa mềm',0,'lo-den-va-vu-tru-so-khai-black-holes-and-baby-universes',110000.00,0),(60,'Bản lĩnh lãnh đạo (Leadership Mastery)',3,4,95000.00,20,'“Bản lĩnh lãnh đạo” là cuốn sách cẩm nang chuyên sâu dành cho các nhà quản lý, giám đốc điều hành và những ai mong muốn xây dựng năng lực dẫn dắt tổ chức. Cuốn sách định nghĩa lãnh đạo không phải là một chức danh hay quyền lực ép buộc, mà là nghệ thuật truyền cảm hứng, gây ảnh hưởng và tạo điều kiện để các thành viên trong tập thể phát huy tối đa tiềm năng của mình. Tác giả phân tích các phẩm chất cốt lõi của một nhà lãnh đạo xuất sắc bao gồm: tầm nhìn chiến lược rõ ràng, sự chính trực trong đạo đức, lòng dũng cảm khi đưa ra quyết định khó khăn và trí tuệ cảm xúc cao để thấu hiểu nhân viên. Sách cung cấp các công cụ thực tế để xây dựng văn hóa doanh nghiệp gắn kết, giải quyết xung đột nội bộ, quản trị sự thay đổi và đào tạo thế hệ kế cận. Bằng các nghiên cứu tình huống thực tế từ các tập đoàn toàn cầu, tác phẩm là nguồn tài liệu quý báu giúp người đọc rèn luyện bản lĩnh kiên cường trước sóng gió thị trường và dẫn dắt tổ chức đạt được những thành công bền vững.','http://res.cloudinary.com/dqiefayjh/image/upload/v1780667906/books/dq914nmp67dxyvldu0bb.jpg',2001,'9786045678936','NXB Tổng Hợp','Tiếng Việt','Bìa mềm',0,'ban-linh-lanh-dao-leadership-mastery',95000.00,0),(61,'Nghệ thuật quản lý thời gian',3,4,79000.00,35,'“Nghệ thuật quản lý thời gian” là cuốn sách thực tiễn tối ưu giúp độc giả giải quyết bài toán nhức nhối của thời đại hiện đại: sự bận rộn quá tải và mất cân bằng cuộc sống. Cuốn sách khẳng định thời gian là tài sản công bằng và quý giá nhất của mỗi người, chúng ta không thể tạo ra thêm thời gian mà chỉ có thể quản lý cách chúng ta sử dụng nó. Tác giả giới thiệu các phương pháp và ma trận quản lý thời gian kinh điển như Ma trận Eisenhower (phân loại công việc theo mức độ quan trọng và khẩn cấp), nguyên lý Pareto 80/20, và kỹ thuật Pomodoro. Sách hướng dẫn người đọc cách thiết lập thứ tự ưu tiên, loại bỏ những tác nhân gây xao nhãng (mạng xã hội, các cuộc họp vô bổ), học cách từ chối và nghệ thuật ủy quyền hiệu quả. Mục tiêu cuối cùng của cuốn sách không phải là biến con người thành một cỗ máy làm việc năng suất, mà giúp họ giải phóng thời gian để dành cho gia đình, sở thích cá nhân và chăm sóc sức khỏe tinh thần.',NULL,1955,'9786045678943','NXB Tổng Hợp','Tiếng Việt','Bìa mềm',0,'nghe-thuat-quan-ly-thoi-gian',79000.00,1),(62,'Để có một cuộc sống hạnh phúc',3,4,85000.00,25,'“Để có một cuộc sống hạnh phúc” là một tác phẩm sâu sắc kết hợp giữa tâm lý học hiện đại và triết lý sống an nhiên, đưa ra những góc nhìn mới mẻ về định nghĩa của hạnh phúc đích thực. Tác giả chỉ ra rằng hạnh phúc không nằm ở những tiêu chuẩn vật chất bên ngoài như tiền tài, địa vị hay danh vọng – những thứ vốn dĩ dễ thay đổi và tạo ra lòng tham vô hạn – mà hạnh phúc là một trạng thái tâm trí, một năng lực cần được rèn luyện hằng ngày từ bên trong. Cuốn sách hướng dẫn người đọc cách thực hành lòng biết ơn, sống trọn vẹn trong khoảnh khắc hiện tại (mindfulness), buông bỏ những oán hận quá khứ và bớt lo lắng về tương lai bất định. Sách cũng nhấn mạnh tầm quan trọng của việc nuôi dưỡng các mối quan hệ gia đình, bạn bè chân thành và tìm kiếm ý nghĩa sống thông qua việc cống hiến cho cộng đồng. Đây là một món quà tinh thần quý giá, một nốt lặng bình yên giúp chữa lành tâm hồn giữa cuộc sống xô bồ, áp lực.',NULL,1946,'9786045678950','NXB Tổng Hợp','Tiếng Việt','Bìa mềm',0,'de-co-mot-cuoc-song-hanh-phuc',85000.00,1),(63,'Thấu hiểu người khác',3,4,89000.00,18,'“Thấu hiểu người khác” là cuốn sách xuất sắc về nghệ thuật giao tiếp và tâm lý học ứng dụng trong các mối quan hệ nhân sinh. Tác giả khẳng định năng lực thấu hiểu người khác là chìa khóa vàng để đạt được sự thành công trong sự nghiệp và hạnh phúc trong cuộc sống gia đình. Cuốn sách cung cấp các kiến thức về cách đọc vị ngôn ngữ cơ thể, nhận biết các nhóm tính cách khác nhau dựa trên các mô hình khoa học (như DISC hay Enneagram) và nghệ thuật lắng nghe chủ động. Thay vì chỉ tập trung vào việc thể hiện cái tôi của bản thân, tác giả khuyến khích người đọc đặt mình vào vị trí của người khác để cảm nhận và chia sẻ, từ đó xây dựng sự đồng cảm và lòng tin cậy sâu sắc. Sách cũng đưa ra các giải pháp khéo léo để hóa giải mâu thuẫn, thuyết phục đối tác và tạo dựng một mạng lưới mối quan hệ xã hội chất lượng, bền vững dựa trên sự tôn trọng lẫn nhau.',NULL,1938,'9786045678967','NXB Tổng Hợp','Tiếng Việt','Bìa mềm',0,'thau-hieu-nguoi-khac',89000.00,1),(64,'Chiến thắng nghịch cảnh',3,4,92000.00,22,'“Chiến thắng nghịch cảnh” là một cuốn sách truyền cảm hứng mạnh mẽ, dành tặng cho những ai đang phải đối mặt với những khó khăn, thất bại hay những biến cố lớn trong cuộc đời. Tác giả chia sẻ một tư duy tích cực: Nghịch cảnh không phải là rào cản bước chân ta, mà là một trường học nghiêm khắc giúp rèn luyện ý chí, bản lĩnh và khai phá những sức mạnh tiềm ẩn mà bình thường chúng ta không nhận ra. Cuốn sách tập hợp những câu chuyện có thật đầy cảm động về những con người phi thường đã vượt qua bạo bệnh, nghèo đói, mất mát để vươn lên đỉnh cao thành công. Qua đó, tác giả đúc kết các bước cụ thể để quản lý cảm xúc tiêu cực, xây dựng tinh thần kiên trì, tái cấu trúc mục tiêu đời mình và hành động quyết liệt để thay đổi hoàn cảnh. Cuốn sách là một điểm tựa tinh thần vững chắc, tiếp thêm ngọn lửa niềm tin và hy vọng để người đọc dũng cảm đứng dậy sau mỗi lần vấp ngã.',NULL,1951,'9786045678974','NXB Tổng Hợp','Tiếng Việt','Bìa mềm',0,'chien-thang-nghich-canh',92000.00,1),(65,'Nghệ thuật thuyết phục lòng người',3,4,88000.00,30,'Hướng dẫn chi tiết các đòn bẩy tâm lý trong giao tiếp để thuyết phục đối tác, khách hàng hoặc đồng nghiệp đồng thuận với ý kiến của mình một cách tự nguyện.',NULL,1940,'9786045678981','NXB Tổng Hợp','Tiếng Việt','Bìa mềm',0,'nghe-thuat-thuyết-phuc-long-nguoi',88000.00,1),(66,'Cấu trúc của Không gian và Thời gian vĩ mô',67,6,150000.00,12,'Tác phẩm chuyên sâu của Stephen Hawking viết chung với George Ellis, thảo luận toán học phức tạp đằng sau lý thuyết tương đối tổng quát của Einstein và các điểm kỳ dị.',NULL,1973,'9786042123512','NXB Trẻ','Tiếng Anh','Bìa cứng',0,'cau-truc-cua-khong-gian-va-thoi-gian-vi-mo',150000.00,1),(67,'Vũ trụ quan thế kỷ mới',67,6,125000.00,15,'Tuyển tập các bài nghiên cứu và nhận định của Stephen Hawking về hướng đi của vật lý lý thuyết và thiên văn học khi nhân loại bước sang thế kỷ 21.',NULL,2002,'9786042123529','NXB Trẻ','Tiếng Việt','Bìa mềm',0,'vu-tru-quan-the-ky-moi',125000.00,1),(68,'Dòng sông chảy từ Eden (A River Out of Eden)',12,6,130000.00,20,'Richard Dawkins sử dụng hình ảnh dòng sông DNA để giải thích cơ chế thông tin di truyền được truyền thừa và phân nhánh liên tục qua hàng triệu năm tiến hóa.','http://res.cloudinary.com/dqiefayjh/image/upload/v1780668134/books/f3rgf7bdpjdmg7f0xszg.jpg',1995,'9786045699942','NXB Khoa Học Kỹ Thuật','Tiếng Việt','Bìa mềm',0,'dong-song-chay-tu-eden-a-river-out-of-eden',130000.00,0),(69,'Phép màu của thực tại (The Magic of Reality)',12,6,195000.00,16,'“Phép màu của thực tại” (The Magic of Reality) là một cuốn sách khoa học phổ thông tuyệt vời được viết bởi Richard Dawkins và minh họa bởi Dave McKean. Cuốn sách được thiết kế dành cho độc giả mọi lứa tuổi, đặc biệt là giới trẻ, nhằm giải thích các hiện tượng tự nhiên bằng lăng kính khoa học thay vì các câu chuyện thần thoại hay phép thuật cổ xưa. Sách đặt ra các câu hỏi lớn như: Ai là người đầu tiên? Vũ trụ được làm bằng gì? Tại sao có ngày và đêm, mùa đông và mùa hè? Mặt trời là gì? Động đất xảy ra như thế nào? Tại sao những điều tồi tệ lại xảy đến với con người? Với mỗi câu hỏi, tác giả trước hết giới thiệu các câu chuyện huyền thoại của các nền văn hóa cổ đại, sau đó giải thích câu trả lời chân thực, chính xác của khoa học hiện đại. Dawkins chứng minh rằng bản thân thực tại khách quan dưới góc nhìn khoa học đã chứa đựng một “phép màu” kỳ vĩ, lôi cuốn và đẹp đẽ hơn bất kỳ câu chuyện giả tưởng nào con người từng nghĩ ra.',NULL,2011,'9786045699959','NXB Khoa Học Kỹ Thuật','Tiếng Việt','Bìa mềm',0,'phep-mau-cua-thuc-tai',195000.00,1),(70,'Một tia lửa trong bóng tối (An Appetite for Wonder)',12,6,165000.00,14,'“Một tia lửa trong bóng tối” (An Appetite for Wonder) là cuốn tự truyện đầu tiên của nhà sinh học tiến hóa lỗi lạc Richard Dawkins. Trong cuốn sách này, tác giả chia sẻ một cách chân thực và giàu cảm xúc về hành trình cuộc đời mình, từ những năm tháng ấu thơ sinh ra tại Kenya, Đông Phi, cho đến quá trình học tập tại Anh và những bước đầu tiên định hình tư duy khoa học tại Đại học Oxford dưới sự dẫn dắt của nhà động vật học nổi tiếng Nikolaas Tinbergen. Cuốn sách hé lộ những nguồn cảm hứng, những cuốn sách và những sự kiện đã khơi dậy trong ông niềm đam mê mãnh liệt đối với thế giới tự nhiên và thuyết tiến hóa. Tác phẩm khép lại ở cột mốc năm 1976, thời điểm ông xuất bản cuốn sách chấn động thế giới “Gen vị kỷ”. Đây không chỉ là câu chuyện cá nhân, mà còn là bức tranh sinh động về đời sống học thuật thế kỷ 20, thể hiện một tâm hồn luôn khao khát tìm kiếm sự thật và một tư duy phản biện sắc bén luôn hướng về ánh sáng khoa học.','http://res.cloudinary.com/dqiefayjh/image/upload/v1780668146/books/zrwjx7rvdu058dwgh7sn.jpg',2013,'9786045699966','NXB Khoa Học Kỹ Thuật','Tiếng Việt','Bìa mềm',0,'mot-tia-lua-trong-bong-toi-an-appetite-for-wonder',165000.00,0),(74,'test sách ẩn',1,1,0.00,10,'Dữ liệu thử nghiệm hệ thống quản lý sách. Cuốn sách này được sử dụng nội bộ để kiểm tra các tính năng hiển thị, bộ lọc bảo mật, phân quyền truy cập và hiển thị trạng thái ẩn/hiện của sản phẩm trên giao diện người dùng (Frontend) và trang quản trị (Backend). Nội dung văn bản này phục vụ mục đích kiểm thử hệ thống (System Testing) nhằm đảm bảo hệ thống cơ sở dữ liệu hoạt động ổn định, chính xác dưới các điều kiện truy vấn khác nhau, đồng thời kiểm tra tính toàn vẹn dữ liệu khi thực hiện các câu lệnh liên kết bảng (JOIN) giữa bảng sách, bảng danh mục và bảng tác giả. Toàn bộ thông tin giá bán, số lượng tồn kho và trạng thái của bản ghi này có thể thay đổi tùy thuộc vào kịch bản kiểm thử của đội ngũ phát triển phần mềm.','',2026,'','','Tiếng Việt','Bìa mềm',0,'test-sach-an',0.00,1),(75,'test sách 2',1,1,0.00,10,'Dữ liệu mẫu thứ hai dành cho quá trình chạy thử nghiệm và tối ưu hóa hiệu năng hệ thống website sách. Bản ghi này hỗ trợ lập trình viên kiểm tra chức năng phân trang (Pagination), hiệu năng tìm kiếm văn bản (Full-text search), và quy trình đồng bộ hóa dữ liệu giữa cơ sở dữ liệu MySQL với các hệ thống lưu trữ đệm (Caching) như Redis hoặc Memcached. Việc duy trì bản ghi kiểm thử giúp phát hiện sớm các lỗi cú pháp phát sinh trong quá trình truy vấn dữ liệu, tối ưu hóa các chỉ mục (Indexes) nhằm tăng tốc độ phản hồi của API, và đảm bảo trải nghiệm người dùng mượt mà nhất trước khi hệ thống chính thức được triển khai lên môi trường sản xuất (Production environment).',NULL,2026,'','','Tiếng Việt','Bìa mềm',0,'test-sach-2',0.00,1),(76,'Clean Code',11,2,189000.00,25,'“Clean Code” (Mã sạch) của tác giả Robert C. Martin (Uncle Bob) là cuốn sách kinh điển, một biểu tượng văn hóa và là tài liệu bắt buộc phải đọc đối với mọi lập trình viên chuyên nghiệp trên thế giới. Cuốn sách tập trung vào việc thay đổi tư duy viết mã, khẳng định rằng viết code chạy được là chưa đủ, code phải “sạch” – tức là phải dễ đọc, dễ hiểu, dễ bảo trì và dễ mở rộng bởi những người khác. Sách được chia thành các phần rõ rệt: phần lý thuyết giới thiệu các nguyên tắc đặt tên biến, tên hàm rõ ràng; cách thiết kế hàm ngắn gọn đơn chức năng; cách viết chú thích hiệu quả và quản lý lỗi hệ thống. Phần tiếp theo đi sâu vào thực hành tái cấu trúc (refactoring) các đoạn mã nguồn phức tạp thành mã sạch thông qua các nghiên cứu tình huống thực tế. Cuốn sách nhấn mạnh nguyên tắc SOLID và tư duy chịu trách nhiệm của người kỹ sư phần mềm đối với từng dòng code mình viết ra, giúp nâng tầm giá trị nghề nghiệp của lập trình viên.','http://res.cloudinary.com/dqiefayjh/image/upload/v1780666553/books/vpjl1z27kvjhedjb3qin.jpg',2008,'9780132350884','Prentice Hall','Tiếng Anh','Bìa mềm',0,'clean-code',220000.00,0),(77,'Clean Architecture',11,2,199000.00,20,'“Refactoring: Improving the Design of Existing Code” của tác giả Martin Fowler là cuốn sách nền tảng định hình lại quy trình phát triển và cải tiến phần mềm hiện đại. Khái niệm “Refactoring” (Tái cấu trúc mã nguồn) được định nghĩa là quá trình thay đổi cấu trúc bên trong của đoạn mã mà không làm thay đổi hành vi bên ngoài của nó, nhằm cải thiện thiết kế, tăng tính dễ đọc và giảm thiểu độ phức tạp của mã nguồn. Cuốn sách cung cấp một danh mục toàn diện các kỹ thuật tái cấu trúc được phân loại rõ ràng, hướng dẫn chi tiết cách phát hiện những “mùi hôi của code” (code smells) – những dấu hiệu cho thấy mã nguồn đang gặp vấn đề về thiết kế. Fowler giải thích cách thực hiện từng bước tái cấu trúc một cách an toàn kết hợp với kiểm thử tự động (automated testing) để đảm bảo không làm phát sinh lỗi mới. Đây là cuốn cẩm nang vô giá giúp các đội ngũ phát triển phần mềm kiểm soát kỹ thuật nợ (technical debt) và duy trì hệ sinh thái mã nguồn khỏe mạnh theo thời gian.','http://res.cloudinary.com/dqiefayjh/image/upload/v1780666537/books/xfesdle15k7tnzepox7p.jpg',2017,'9780134494166','Prentice Hall','Tiếng Anh','Bìa mềm',0,'clean-architecture',230000.00,0),(78,'The Clean Coder',11,2,179000.00,18,'“Design Patterns: Elements of Reusable Object-Oriented Software” viết bởi nhóm tác giả Erich Gamma, Richard Helm, Ralph Johnson và John Vlissides (được biết đến rộng rãi với tên gọi Gang of Four - GoF) là cuốn sách đặt nền móng cho kiến trúc phần mềm hướng đối tượng. Cuốn sách giới thiệu 23 mẫu thiết kế chuẩn hóa (design patterns), được chia thành 3 nhóm chính: Nhóm khởi tạo (Creational), Nhóm cấu trúc (Structural), và Nhóm hành vi (Behavioral). Mỗi mẫu thiết kế đại diện cho một giải pháp tối ưu đã được chứng minh thực tế để giải quyết các vấn đề phổ biến, lặp đi lặp lại trong quá trình thiết kế phần mềm. Sách giải thích chi tiết sơ đồ lớp (Class diagrams), vai trò của từng đối tượng và cách chúng tương tác phối hợp với nhau để tạo ra một hệ thống phần mềm linh hoạt, dễ mở rộng và giảm thiểu sự phụ thuộc lẫn nhau (loose coupling). Đây là tài liệu chuyên sâu nâng tầm tư duy của một lập trình viên bình thường trở thành một kiến trúc sư phần mềm thực thụ.','http://res.cloudinary.com/dqiefayjh/image/upload/v1780666526/books/dksrzzpadh4mx8cwj4sp.jpg',2011,'9780137081073','Prentice Hall','Tiếng Anh','Bìa mềm',0,'the-clean-coder',210000.00,0),(79,'Introduction to Algorithms',13,2,390000.00,10,'“Code Complete” của Steve McConnell được coi là cuốn bách khoa toàn thư toàn diện và thực tiễn nhất về quy trình xây dựng phần mềm (software construction). Trải qua nhiều thập kỷ, cuốn sách vẫn giữ nguyên giá trị cốt lõi khi tập trung vào giai đoạn cốt lõi của dự án: lập trình và kiểm thử. McConnell tổng hợp những nghiên cứu khoa học và kinh nghiệm thực tế tốt nhất của ngành công nghiệp phần mềm để hướng dẫn chi tiết từ việc lập kế hoạch thiết kế kiến trúc, tổ chức dữ liệu, kỹ thuật viết câu lệnh điều kiện, vòng lặp, đến việc quản lý chất lượng mã nguồn thông qua rà soát code (code reviews) và gỡ lỗi (debugging). Cuốn sách phân tích sâu sắc các yếu tố ảnh hưởng đến năng suất của lập trình viên và chất lượng dự án như quy mô đội ngũ, quản lý thời gian và các thói quen làm việc. Với độ dày và hàm lượng kiến thức đồ sộ, tác phẩm là người bạn đồng hành không thể thiếu, giúp mọi kỹ sư phần mềm tối ưu hóa quy trình làm việc và tạo ra những sản phẩm phần mềm xuất sắc nhất.','http://res.cloudinary.com/dqiefayjh/image/upload/v1780666512/books/w1fkverhcfdlwtmmi9ow.jpg',2009,'9780262033848','MIT Press','Tiếng Anh','Bìa cứng',0,'introduction-to-algorithms',450000.00,0),(80,'Algorithms Unlocked',13,2,180000.00,15,'Algorithms Unlocked được viết nhằm giúp người đọc tiếp cận thế giới thuật toán một cách dễ hiểu hơn. Thomas H. Cormen giải thích các khái niệm phức tạp bằng ngôn ngữ đơn giản, phù hợp cho cả người không chuyên.\n\nCuốn sách là lựa chọn lý tưởng cho những ai muốn hiểu nền tảng của khoa học máy tính trước khi nghiên cứu các tài liệu chuyên sâu hơn.','http://res.cloudinary.com/dqiefayjh/image/upload/v1780653709/books/qudvk5s6t1ee98ew46ks.jpg',2013,'9780262518802','MIT Press','Tiếng Anh','Bìa mềm',0,'algorithms-unlocked',220000.00,0),(81,'The Pragmatic Programmer',14,2,215000.00,20,'The Pragmatic Programmer là một trong những cuốn sách có ảnh hưởng lớn nhất trong ngành phát triển phần mềm. Tác phẩm cung cấp nhiều lời khuyên thực tế về thiết kế hệ thống, viết mã, học tập liên tục và giải quyết vấn đề.\n\nDù công nghệ thay đổi theo thời gian, các nguyên tắc được trình bày trong sách vẫn giữ nguyên giá trị đối với các lập trình viên ở mọi cấp độ kinh nghiệm.','http://res.cloudinary.com/dqiefayjh/image/upload/v1780653723/books/vwbevzqcwtflyigljjaj.jpg',1999,'9780201616224','Addison-Wesley','Tiếng Anh','Bìa mềm',0,'the-pragmatic-programmer',250000.00,0),(82,'Pragmatic Thinking and Learning',14,2,185000.00,16,'Pragmatic Thinking and Learning khám phá cách bộ não tiếp nhận và xử lý thông tin trong quá trình học tập. Tác giả đưa ra nhiều phương pháp giúp lập trình viên nâng cao khả năng tư duy, ghi nhớ và giải quyết vấn đề.\n\nCuốn sách kết hợp giữa khoa học nhận thức và kinh nghiệm thực tiễn để giúp người đọc học nhanh hơn và làm việc hiệu quả hơn.','http://res.cloudinary.com/dqiefayjh/image/upload/v1780653740/books/x15nb4jc5exbc7gerekc.jpg',2008,'9781934356050','Pragmatic Bookshelf','Tiếng Anh','Bìa mềm',0,'pragmatic-thinking-and-learning',220000.00,0),(83,'Designing Data-Intensive Applications',15,2,320000.00,12,'Cuốn sách nổi tiếng về thiết kế hệ thống và xử lý dữ liệu hiện đại, dành cho lập trình viên, kỹ sư phần mềm và kiến trúc sư hệ thống. Cuốn sách giải thích các nguyên lý nền tảng đằng sau những công nghệ được sử dụng trong các ứng dụng quy mô lớn như cơ sở dữ liệu quan hệ và NoSQL, hệ thống phân tán, lưu trữ dữ liệu, sao chép dữ liệu và khả năng mở rộng hệ thống. Thay vì tập trung vào một công nghệ cụ thể, tác giả giúp người đọc hiểu cách các hệ thống dữ liệu hoạt động và cách lựa chọn giải pháp phù hợp cho từng bài toán thực tế.\r\n\r\nNội dung sách bao gồm các chủ đề quan trọng như mô hình dữ liệu, giao dịch, tính nhất quán, phân vùng dữ liệu, xử lý dữ liệu theo lô và xử lý luồng dữ liệu. Với nhiều ví dụ thực tế cùng cách trình bày dễ hiểu, cuốn sách giúp người đọc xây dựng nền tảng vững chắc về kiến trúc hệ thống hiện đại và phát triển tư duy thiết kế các ứng dụng đáng tin cậy, hiệu suất cao. Đây được xem là một trong những tài liệu tham khảo giá trị nhất dành cho những ai muốn tìm hiểu chuyên sâu về backend, cơ sở dữ liệu và hệ thống phân tán.','http://res.cloudinary.com/dqiefayjh/image/upload/v1780653441/books/ykkzjlnpdlxbocue6zyx.jpg',2017,'9781449373320','Reilly Media','Tiếng Anh','Bìa mềm',0,'designing-dataintensive-applications',380000.00,0);
