INSERT INTO `reviews` VALUES (2,19,1,4,'nhận dduocj hàng cũng nhanh, sách ok như hình','2026-04-19 06:55:50',NULL),(646,1,1,5,'Sách rất hay, đọc rất cuốn!','2026-05-31 12:09:45',NULL),(647,1,1,4,'Nội dung tốt, giao hàng nhanh.','2026-05-31 12:09:45',NULL),(648,1,1,3,'Bình thường, không có gì đặc biệt.','2026-05-31 12:09:45',NULL),(649,1,1,5,'Tuyệt vời, sẽ mua lại!','2026-05-31 12:09:45',NULL),(650,1,1,2,'Hơi thất vọng.','2026-05-31 12:09:45',NULL),(651,1,1,5,'Cuốn sách gợi lại bao ký ức tuổi thơ, đọc xong thấy ấm lòng lắm!','2026-05-31 12:12:34',NULL),(652,1,1,4,'Văn phong nhẹ nhàng, dễ đọc. Rất phù hợp để thư giãn.','2026-05-31 12:12:34',NULL),(653,1,1,3,'Bình thường, không có gì đặc biệt so với các tác phẩm khác của tác giả.','2026-05-31 12:12:34',NULL),(654,1,1,5,'Tuyệt vời! Mình đọc một mạch không nghỉ.','2026-05-31 12:12:34',NULL),(655,1,1,2,'Hơi thất vọng, mình kỳ vọng nhiều hơn.','2026-05-31 12:12:34',NULL),(656,1,1,4,'Sách in đẹp, chất lượng giấy tốt, nội dung hay.','2026-05-31 12:12:34',NULL),(657,1,1,5,'Món quà tuyệt vời cho các bé nhỏ trong nhà!','2026-05-31 12:12:34',NULL),(658,2,1,5,'Thay đổi hoàn toàn tư duy tài chính của mình sau khi đọc xong!','2026-05-31 12:12:34',NULL),(659,2,1,4,'Kiến thức rất thực tế, dễ áp dụng vào cuộc sống.','2026-05-31 12:12:34',NULL),(660,2,1,3,'Đọc rồi nhưng khó áp dụng ở Việt Nam lắm.','2026-05-31 12:12:34',NULL),(661,2,1,5,'Cuốn sách gối đầu giường của mình, đọc đi đọc lại nhiều lần.','2026-05-31 12:12:34',NULL),(662,2,1,4,'Rất hay cho người mới bắt đầu tìm hiểu về tài chính.','2026-05-31 12:12:34',NULL),(663,2,1,1,'Nội dung lặp đi lặp lại, không có gì mới.','2026-05-31 12:12:34',NULL),(664,3,1,5,'Đọc xong khóc cả buổi, câu chuyện tình yêu quá đẹp và buồn.','2026-05-31 12:12:34',NULL),(665,3,1,5,'Tác phẩm hay nhất của Nguyễn Nhật Ánh theo mình.','2026-05-31 12:12:34',NULL),(666,3,1,4,'Cảm xúc dâng trào, lối viết tinh tế và chân thật.','2026-05-31 12:12:34',NULL),(667,3,1,3,'Hơi dài ở đoạn giữa nhưng kết thúc rất hay.','2026-05-31 12:12:34',NULL),(668,3,1,5,'Đã xem phim rồi nhưng đọc sách vẫn hay hơn nhiều!','2026-05-31 12:12:34',NULL),(669,3,1,4,'Nhân vật Hà Lan để lại ấn tượng rất sâu trong lòng mình.','2026-05-31 12:12:34',NULL),(670,6,1,5,'Cuốn sách kinh điển mọi người nên đọc ít nhất một lần trong đời.','2026-05-31 12:12:34',NULL),(671,6,1,4,'Nhiều bài học quý giá về cách ứng xử và giao tiếp.','2026-05-31 12:12:34',NULL),(672,6,1,5,'Áp dụng vào công việc thấy hiệu quả rõ rệt!','2026-05-31 12:12:34',NULL),(673,6,1,3,'Một số nguyên tắc hơi cũ, không còn phù hợp lắm với thời hiện đại.','2026-05-31 12:12:34',NULL),(674,6,1,4,'Đọc lần 2 vẫn rút ra được nhiều điều mới.','2026-05-31 12:12:34',NULL),(675,6,1,5,'Sách giao hàng nhanh, đóng gói cẩn thận, nội dung tuyệt vời!','2026-05-31 12:12:34',NULL),(676,8,1,5,'Cuốn sách mở mang tầm nhìn về lịch sử loài người, đọc không thể dừng lại.','2026-05-31 12:12:34',NULL),(677,8,1,5,'Harari viết rất cuốn hút dù đề tài khá nặng.','2026-05-31 12:12:34',NULL),(678,8,1,4,'Cần đọc chậm để thấm, nhưng rất xứng đáng bỏ thời gian.','2026-05-31 12:12:34',NULL),(679,8,1,3,'Hay nhưng hơi khô khan ở một số chương.','2026-05-31 12:12:34',NULL),(680,8,1,4,'Thay đổi cách mình nhìn nhận xã hội và con người.','2026-05-31 12:12:34',NULL),(681,9,1,5,'Triết lý sâu sắc, mỗi lần đọc lại thấy một điều mới.','2026-05-31 12:12:34',NULL),(682,9,1,5,'Cuốn sách truyền cảm hứng nhất mình từng đọc!','2026-05-31 12:12:34',NULL),(683,9,1,4,'Ngắn nhưng đầy ý nghĩa, rất phù hợp để tặng bạn bè.','2026-05-31 12:12:34',NULL),(684,9,1,3,'Hành trình hơi đơn giản, nhưng thông điệp đẹp.','2026-05-31 12:12:34',NULL),(685,9,1,5,'Câu chuyện về ước mơ và hành trình theo đuổi nó rất chạm lòng.','2026-05-31 12:12:34',NULL),(686,12,1,5,'Tuổi thơ của cả một thế hệ! Đọc lại vẫn thấy hay như lần đầu.','2026-05-31 12:12:34',NULL),(687,12,1,5,'Thế giới phép thuật được xây dựng cực kỳ chi tiết và hấp dẫn.','2026-05-31 12:12:34',NULL),(688,12,1,4,'Bản dịch tiếng Việt khá tốt, giữ được cái hồn của nguyên tác.','2026-05-31 12:12:34',NULL),(689,12,1,5,'Con mình mê lắm, đọc một mạch hết luôn!','2026-05-31 12:12:34',NULL),(690,12,1,3,'Hay nhưng mình thích các phần sau hơn phần đầu này.','2026-05-31 12:12:34',NULL),(691,14,1,3,'ờm... khó lói','2026-06-06 11:01:04',NULL),(692,16,1,5,'bìa sách đẹp nhìn ưng bụng, nội dung thì đỉnh của chóp','2026-06-06 11:02:22',NULL),(693,18,1,5,'Mình mua cuốn này vì tò mò và hoàn toàn bị thuyết phục. Không chỉ giải thích về vật lý, cuốn sách còn truyền cảm hứng mạnh mẽ về khát khao hiểu biết của con người trước vũ trụ bao la. Giao hàng nhanh, sách không bị móp méo góc. Sẽ tiếp tục ủng hộ shop ở những cuốn tiếp theo!','2026-06-06 11:35:02',NULL);
